// Additive rich-content module for location detail pages.
// Keyed by the RENDERED location slug (see lib/data/locations.ts / data/batches/locations).
// This module is intentionally separate from lib/data/locations.ts so the existing
// batch-driven Location records (description, highlights, default faqs) are untouched.
// The [slug] page renders these sections between the description and the FAQ block,
// and prefers these faqs over the thinner batch-sourced ones, falling back when absent.
//
// Content for the 14 DFW-suburb entries below was adapted from the rich, already-authored
// JSON files at the repo root (/locations/*.json), which existed but were never wired into
// the rendered page. The remaining entries (Uptown Dallas, Downtown Dallas, Deep Ellum,
// Design District, Bishop Arts, Flower Mound, Dallas, and Nationwide) were authored fresh
// since no matching root-level JSON existed for those rendered slugs.

export type LocationContentSection = {
  heading: string | null;
  html: string;
};

export type LocationContentFaq = {
  question: string;
  answer: string;
};

export type LocationContentEntry = {
  sections: LocationContentSection[];
  faqs: LocationContentFaq[];
};

export const locationContent: Record<string, LocationContentEntry> = {
  "uptown-dallas-tx": {
    sections: [
      { heading: null, html: `<p>Uptown Dallas is the densest, most tightly held submarket in the metro, and an owner selling here is almost always sitting on a high-rise multifamily tower, a Class A office floor near McKinney Avenue, or a ground-floor retail condo tied to the West Village or Knox-Henderson edge. The trolley-served corridor between the Katy Trail and Central Expressway trades on scarcity, so replacement search timelines look different from a suburban exchange where comparable product is easy to find.</p>` },
      { heading: `McKinney Avenue Trolley Corridor Multifamily and Mixed-Use`, html: `<p>The bulk of Uptown sale activity we see involves high-rise or mid-rise multifamily along the trolley line, where towers like those near the Katy Trail trade on walkability and concierge amenities rather than pure cap rate. An owner exiting one of these buildings is typically comparing against other trophy or near-trophy multifamily in Uptown, Knox-Henderson, or the Harwood District rather than suburban garden-style product, since the tenant profile and rent basis do not line up otherwise.</p>` },
      { heading: `Office Floors Near the Harwood District and West Village Retail`, html: `<p>Uptown office sits close to the Harwood District's newer towers, and a seller exiting a Class A office floor here usually wants to know whether staying in urban office, moving into Uptown-adjacent medical office, or diversifying into a West Village-style retail condo makes more sense for the replacement search. West Village and Knox Street retail carries some of the highest per-square-foot rents in Dallas, driven by restaurant and boutique tenants willing to pay for foot traffic, which changes how a retail replacement candidate should be underwritten compared to a suburban strip center.</p>` },
      { heading: `Identification Strategy When Uptown Product Is This Tightly Held`, html: `<p>Because so little Uptown inventory turns over in a given year, investors trading within the neighborhood often need the two hundred percent rule rather than the three property rule, simply to keep enough live candidates on the list while offers are being negotiated. Someone willing to widen the search to Knox-Henderson, the Harwood District, or greater North Dallas usually has an easier time building a clean three property list without needing the broader rule.</p>` },
      { heading: `Diligence on Parking, HOA-Style Assessments, and Concierge Costs`, html: `<p>High-rise product in Uptown carries operating costs that a suburban buyer does not expect, including concierge staffing, elevator maintenance reserves, and parking garage assessments that function much like an HOA fee on the commercial side. A buyer should get trailing twelve month common area expense detail broken out separately from unit-level operating costs, because a building with deferred garage or elevator capital work can look deceptively cheap on a per-door basis until that capital need surfaces.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Uptown's Compressed Cap Rates`, html: `<p>Lenders underwriting Uptown acquisitions look closely at trailing occupancy and concession trends, since compressed cap rates leave less room for a debt service shortfall to be absorbed by rent growth alone. We coordinate with the qualified intermediary and lender early so that a competitive, multiple-offer Uptown listing does not get lost while financing details are still being worked out, which happens more often here than in slower-moving suburban markets.</p>` },
    ],
    faqs: [
      { question: `Why does Uptown Dallas multifamily trade at tighter cap rates than the suburbs?`, answer: `Walkability to the Katy Trail, West Village, and Knox Street restaurants supports rents that suburban garden-style product cannot match, and limited buildable land keeps new supply constrained, both of which compress cap rates relative to Plano or Frisco multifamily.` },
      { question: `Should I widen my search beyond Uptown if I want to use the three property rule?`, answer: `Often yes. Uptown inventory turns over slowly, so investors who want to stay inside the three property rule frequently need to include Knox-Henderson, the Harwood District, or broader North Dallas candidates rather than limiting the list to Uptown alone.` },
      { question: `What operating costs are easy to miss in a high-rise Uptown building?`, answer: `Parking garage capital reserves, elevator maintenance, and concierge staffing costs are often bundled into common area expenses in a way that is not obvious from a simple per-door income statement, so a buyer should request that detail broken out separately.` },
      { question: `Is West Village or Knox Street retail a good 1031 replacement for an Uptown office seller?`, answer: `It can be, since both trade on strong foot traffic and restaurant demand, but the underwriting approach differs from office. A seller should treat the retail candidate on its own tenant mix and lease structure rather than assuming Uptown proximity alone makes it comparable to the office asset being sold.` },
      { question: `Can 1031 Exchange Dallas confirm my Uptown property qualifies for an exchange?`, answer: `No. We coordinate identification, property sourcing, and communication between your advisors. Whether a specific Uptown transaction qualifies for tax deferral is a determination made by your CPA, tax attorney, and qualified intermediary.` },
    ],
  },
  "downtown-dallas-tx": {
    sections: [
      { heading: null, html: `<p>Downtown Dallas is in the middle of a multi-year shift as older office towers convert to residential and hospitality use, and an owner selling property here is often dealing with either a conversion candidate, a stabilized building near the AT&T Discovery District, or a Main Street District property carrying historic designation. Each of those has a distinct replacement search attached to it.</p>` },
      { heading: `Downtown's Office-to-Residential Conversion Wave`, html: `<p>Several former bank and insurance towers downtown have been converted or are being evaluated for conversion to apartments, and an owner exiting a partial-interest or ground lease position tied to one of these projects needs replacement candidates evaluated on construction risk and lease-up timeline rather than stabilized occupancy alone. That is a different underwriting exercise than a straightforward stabilized office trade, and the identification list should reflect the added completion risk. Vacancy in Downtown's remaining office stock has also pushed some landlords toward conversion studies even without a signed construction contract, which means a seller should distinguish between a building that is genuinely under conversion and one that is simply being marketed with conversion potential attached to the listing.</p>` },
      { heading: `Main Street District Historic Buildings and Tax Credit Considerations`, html: `<p>Properties in the Main Street District often carry federal or state historic designations, and an owner selling one of these buildings should confirm with their tax advisor how any historic tax credit recapture interacts with the 1031 exchange timeline, since recapture exposure is a separate issue from capital gains deferral and does not automatically follow the replacement property into a new ownership structure.</p>` },
      { heading: `AT&T Discovery District and Convention Center Hospitality Demand`, html: `<p>The AT&T Discovery District and the nearby convention center corridor support hospitality and entertainment-adjacent retail demand that does not exist in most other downtown submarkets, and an investor identifying hospitality replacement candidates here should weigh convention calendar seasonality against a more stable office or retail alternative before finalizing the identification list. Restaurant and retail pads oriented toward event traffic in this corridor also see meaningfully different weekday and weekend patterns than a neighborhood retail center, which should factor into how a buyer projects year-round occupancy for those tenant categories.</p>` },
      { heading: `Identification Timing for Conversion and Value-Add Downtown Product`, html: `<p>Conversion and value-add downtown deals often move on a slower timeline than a stabilized suburban trade, since construction lenders and equity partners need more time to underwrite completion risk. We generally recommend the two hundred percent rule for these searches so a backup stabilized candidate stays on the list in case a conversion deal cannot close inside the one hundred eighty day window.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Historic Downtown Deals`, html: `<p>Lenders financing historic or conversion product downtown typically require more third party reporting than a standard commercial loan, including a property condition assessment scoped specifically to the conversion plan. We start that coordination with the qualified intermediary as soon as a downtown candidate is identified, since historic downtown financing timelines rarely compress well inside the final weeks before day one hundred eighty.</p>` },
    ],
    faqs: [
      { question: `Does a historic tax credit on a Main Street District building affect my 1031 exchange?`, answer: `Potentially. Historic tax credit recapture is a separate issue from capital gains deferral, and the two do not automatically move together into a replacement property. An investor should confirm the interaction with their CPA or tax attorney before finalizing a Main Street District sale.` },
      { question: `Why does downtown office-to-residential conversion product take longer to close?`, answer: `Conversion projects carry construction and lease-up risk that a stabilized asset does not, so construction lenders and equity partners typically require more underwriting time, which is why we usually recommend keeping a stabilized backup candidate on the identification list.` },
      { question: `Is convention center hospitality demand a stable basis for a downtown Dallas exchange?`, answer: `It can be strong but is more seasonal than a typical office or retail lease structure, since it tracks the convention calendar. An investor should weigh that seasonality against a more stable alternative before committing to a hospitality-only identification list.` },
      { question: `Should I use the three property rule or 200 percent rule for a downtown conversion trade?`, answer: `We generally recommend the 200 percent rule when a conversion candidate is involved, since it allows a stabilized backup property to stay on the list if the conversion deal cannot close inside the exchange deadlines.` },
      { question: `Can 1031 Exchange Dallas confirm my downtown property qualifies for an exchange?`, answer: `No. Our role is coordinating identification, sourcing, and communication among your advisors. Whether a specific downtown transaction qualifies is determined by your CPA, tax attorney, and qualified intermediary.` },
    ],
  },
  "deep-ellum-tx": {
    sections: [
      { heading: null, html: `<p>Deep Ellum's commercial base is built on warehouse buildings that have been adapted into creative office, live music venues, and independent retail, and the neighborhood's identity as an entertainment district shapes what a replacement search should actually prioritize. An owner selling here is rarely dealing with a conventional office or retail asset in the suburban sense.</p>` },
      { heading: `Warehouse-to-Creative-Office Adaptive Reuse Along Elm and Main`, html: `<p>Much of Deep Ellum's commercial stock started as early twentieth century warehouse and light industrial buildings along Elm and Main Streets, later converted to creative office, gallery, and restaurant space. An investor exchanging out of one of these buildings should confirm what structural or code work was actually completed during a prior conversion, since exposed brick and open ceilings can hide deferred building system work behind the aesthetic. Ceiling height and column spacing in these older warehouse floor plates also limit which creative office or restaurant layouts actually fit, so a buyer should walk the space with a specific tenant use in mind rather than assuming the shell is universally adaptable.</p>` },
      { heading: `Entertainment and Live Music Venue Tenant Risk`, html: `<p>Live music venues and bars anchor a meaningful share of Deep Ellum ground floor retail, and that tenant category carries more revenue volatility and turnover risk than a standard retail lease, since venue economics depend heavily on touring schedules and late-night foot traffic that can shift quickly with neighborhood perception. A buyer should weigh percentage rent structures and venue-specific lease terms carefully rather than treating this income the same as a national retail tenant.</p>` },
      { heading: `The Epic District's Newer Office and Multifamily Supply`, html: `<p>Just south of Deep Ellum's original core, the Epic District has added newer Class A office and multifamily supply that competes for some of the same tenant base as older Deep Ellum buildings, which has put pricing pressure on legacy adaptive reuse product. An investor should factor that newer competing supply into any hold-versus-exchange decision on an older Deep Ellum asset. A tenant choosing between a renovated Epic District tower and a converted Deep Ellum warehouse is often weighing amenity and parking convenience against neighborhood character, and an owner should be honest about which side of that trade-off their building sits on before setting rent expectations for a replacement search.</p>` },
      { heading: `Identification Timing for Deep Ellum's Adaptive Reuse Stock`, html: `<p>Because adaptive reuse buildings trade less frequently than standard office or retail product, an investor exchanging within Deep Ellum specifically often needs the two hundred percent rule to keep enough candidates on the list, while someone willing to widen the search to the Epic District or greater East Dallas can usually work within the three property rule.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Entertainment-District Assets`, html: `<p>Lenders financing entertainment-district property in Deep Ellum typically want percentage rent history and venue-specific lease detail before committing, since standard debt service coverage math undersells the volatility in this tenant category. We coordinate that documentation with the qualified intermediary early so financing does not stall a Deep Ellum acquisition close to the one hundred eighty day deadline.</p>` },
    ],
    faqs: [
      { question: `What should I check before buying an adaptive reuse warehouse building in Deep Ellum?`, answer: `Confirm what structural, electrical, and mechanical work was actually completed during any prior conversion. Exposed brick and open ceiling finishes can make a building look updated while the underlying systems still need work.` },
      { question: `Are live music venues a reliable retail tenant for a Deep Ellum 1031 replacement?`, answer: `They can generate strong income but carry more revenue volatility than standard retail, since venue economics depend on touring schedules and shifting neighborhood foot traffic. Percentage rent structures should be reviewed carefully rather than treated like a fixed national tenant lease.` },
      { question: `How does the Epic District affect legacy Deep Ellum property values?`, answer: `Newer Class A office and multifamily supply in the Epic District competes for some of the same tenants as older Deep Ellum buildings, which can pressure pricing on legacy adaptive reuse stock and is worth factoring into a hold-versus-exchange decision.` },
      { question: `Should I use the three property rule for a Deep Ellum-only replacement search?`, answer: `It depends on how narrow the search is. Staying strictly within Deep Ellum's limited adaptive reuse inventory often calls for the 200 percent rule, while widening the search to the Epic District or East Dallas usually makes the three property rule workable.` },
      { question: `Can 1031 Exchange Dallas confirm my Deep Ellum property qualifies for an exchange?`, answer: `No. We coordinate property identification and communication with your advisors. Whether a specific Deep Ellum transaction qualifies for tax deferral is determined by your CPA, tax attorney, and qualified intermediary.` },
    ],
  },
  "design-district-tx": {
    sections: [
      { heading: null, html: `<p>The Dallas Design District sits between the Trinity River and Stemmons Freeway and has shifted from a pure furniture and showroom market into a mix of creative office, restaurant, and newer multifamily product. An owner selling here is usually holding a showroom building being repositioned, a Trinity Groves-area restaurant pad, or a newer mixed-use property near Sylvan Thirty.</p>` },
      { heading: `Showroom-to-Creative-Office Conversion Along Hi Line Drive`, html: `<p>Design District showroom buildings along Hi Line Drive and Slocum Street have increasingly been converted or repositioned into creative office and event space as furniture and design tenants have consolidated elsewhere. An owner exchanging out of one of these buildings should confirm current occupancy against the building's original showroom use, since a partially repositioned building often carries a mix of legacy and new tenant types that behave differently. Loading dock access and floor load capacity built for furniture delivery can be a selling point for a creative office or event tenant, but it can just as easily sit unused and add no value once the building's use shifts, so an owner should price that feature based on actual tenant demand rather than the building's original design intent.</p>` },
      { heading: `Trinity Groves Restaurant Incubator and Retail Pads`, html: `<p>Trinity Groves functions as a restaurant incubator, with concepts frequently opening, closing, or relocating within the development, which means retail pad income here carries more turnover risk than a stabilized net lease tenant elsewhere in Dallas. A buyer should ask for concept-level tenure history rather than relying on the property's overall occupancy rate.</p>` },
      { heading: `Sylvan Thirty and the District's Newer Mixed-Use Product`, html: `<p>Sylvan Thirty and similar newer developments have introduced ground-floor retail with multifamily or office above, giving the Design District a mixed-use product type that did not exist here a decade ago. An investor comparing this newer product against older showroom buildings should treat them as separate categories in the identification list rather than assuming geographic proximity makes them interchangeable. The multifamily component in these newer projects also draws a different resident profile than the district's older warehouse-adjacent housing, which affects how the ground-floor retail below it should be leased and underwritten.</p>` },
      { heading: `Identification Timing for Design District Conversion Plays`, html: `<p>Because much of the Design District's inventory is mid-repositioning, an investor targeting conversion candidates here often needs the two hundred percent rule to keep both partially repositioned and fully stabilized options open, since a conversion deal can stall on financing or entitlement issues that a stabilized property does not face.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Adaptive Reuse Financing`, html: `<p>Lenders financing Design District repositioning projects typically want a clear scope of remaining conversion work and a realistic stabilization timeline before committing. We coordinate that documentation with the qualified intermediary as soon as a Design District candidate is identified, since adaptive reuse underwriting tends to move slower than a standard stabilized acquisition.</p>` },
    ],
    faqs: [
      { question: `Is a Design District showroom building still viable as a 1031 replacement property?`, answer: `It can be, but a buyer should confirm current occupancy against the building's original showroom use, since many of these buildings are mid-repositioning into creative office and carry a mix of legacy and new tenants that behave differently.` },
      { question: `How reliable is Trinity Groves restaurant income for underwriting?`, answer: `Trinity Groves functions as a restaurant incubator with frequent concept turnover, so a buyer should request concept-level tenure history rather than relying on the property's overall occupancy figure to represent income stability.` },
      { question: `Should I compare Sylvan Thirty-style mixed-use product to older Design District showroom buildings?`, answer: `Generally no. They are different product types with different tenant profiles and underwriting approaches, and treating them as interchangeable just because they sit in the same district can lead to a mismatched replacement decision.` },
      { question: `Why does the 200 percent rule come up so often for Design District exchanges?`, answer: `Much of the district's inventory is mid-repositioning, so keeping both stabilized and conversion-stage candidates on the identification list usually requires the 200 percent rule rather than the narrower three property rule.` },
      { question: `Can 1031 Exchange Dallas confirm my Design District property qualifies for an exchange?`, answer: `No. We coordinate identification and communication among your advisors. Whether a specific Design District transaction qualifies for tax deferral is determined by your CPA, tax attorney, and qualified intermediary.` },
    ],
  },
  "bishop-arts-tx": {
    sections: [
      { heading: null, html: `<p>The Bishop Arts District in Oak Cliff has become one of Dallas's most walkable boutique retail and restaurant corridors, built largely out of converted early twentieth century bungalows and small commercial buildings. An owner selling here is typically holding a small-footprint retail or restaurant building rather than the larger single-tenant product common elsewhere in the metro.</p>` },
      { heading: `Bungalow-to-Retail Conversions Along Bishop Avenue and West Davis`, html: `<p>Many Bishop Arts storefronts started as residential bungalows converted to commercial use, which means building systems, parking, and ADA access often need closer scrutiny than a purpose-built retail structure would. An investor exchanging out of one of these buildings should confirm what conversion work was permitted versus done informally, since informal conversions can surface as code issues during a buyer's due diligence. On-site parking is frequently limited to what a former residential driveway can hold, so many operators lean on street parking and nearby paid lots, and a buyer should confirm the actual parking arrangement a tenant relies on rather than assuming a code-compliant on-site count exists.</p>` },
      { heading: `Boutique Restaurant and Retail Pad Turnover in a Walkable District`, html: `<p>Bishop Arts leases skew toward independent restaurant and boutique retail concepts rather than national credit tenants, and that tenant mix turns over more frequently than a typical net lease property. A buyer should review lease term length and personal guarantee structure carefully, since an independent operator's lease commitment carries different risk than a corporate tenant's. Foot traffic here concentrates heavily around Bishop Avenue's core blocks and drops off within a few blocks in either direction, so location within the district matters more for an independent operator's success than it would for a destination tenant with its own regional draw.</p>` },
      { heading: `Land Value Compression as Oak Cliff Gentrifies`, html: `<p>Land values around Bishop Arts have risen faster than rents in some blocks as Oak Cliff redevelopment has accelerated, which compresses going-in cap rates for new buyers even where in-place income has not grown as quickly. An investor should model rent growth assumptions conservatively rather than extrapolating recent land price trends directly onto expected income.</p>` },
      { heading: `Identification Timing for Small-Footprint Bishop Arts Retail`, html: `<p>Because individual Bishop Arts buildings are small and trade infrequently, an investor targeting this specific district often needs the two hundred percent rule to build out a workable identification list, while someone willing to widen the search to greater Oak Cliff or nearby Kessler Park can usually stay within the three property rule.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Compact Retail Deals`, html: `<p>Lenders financing small Bishop Arts retail buildings often apply more scrutiny to tenant financial strength given the independent operator base, and a buyer should expect requests for personal guarantees or additional reserves. We coordinate with the qualified intermediary early so those additional underwriting steps do not create a late surprise before the closing date.</p>` },
    ],
    faqs: [
      { question: `What should I check before buying a converted bungalow storefront in Bishop Arts?`, answer: `Confirm what conversion work from residential to commercial use was actually permitted, since informal conversions can surface as code or ADA access issues during due diligence that would not appear in a purpose-built commercial structure.` },
      { question: `Is independent restaurant tenant income in Bishop Arts a stable basis for underwriting?`, answer: `It can generate strong rent but carries more turnover risk than a national credit tenant, so lease term length and personal guarantee structure should be reviewed carefully rather than assuming the income is as stable as a corporate net lease tenant.` },
      { question: `Why are Bishop Arts cap rates compressing even where rents have not grown as fast?`, answer: `Land values in Oak Cliff have risen quickly as the neighborhood redevelops, which compresses going-in cap rates for new buyers independent of in-place rent growth, so income projections should stay conservative rather than following recent land price trends.` },
      { question: `Should I use the three property rule for a Bishop Arts-only search?`, answer: `Staying strictly within Bishop Arts often requires the 200 percent rule given how infrequently these small buildings trade, while widening the search to greater Oak Cliff or Kessler Park usually makes the three property rule workable.` },
      { question: `Can 1031 Exchange Dallas confirm my Bishop Arts property qualifies for an exchange?`, answer: `No. We coordinate property sourcing and communication among your advisors. Whether a specific Bishop Arts transaction qualifies for tax deferral is determined by your CPA, tax attorney, and qualified intermediary.` },
    ],
  },
  "plano-tx": {
    sections: [
      { heading: null, html: `<p>Plano's commercial base still carries the imprint of the corporate relocations that built Legacy West and Legacy Business Park, and that history shapes what an exchanger finds when shopping replacement property here. Class A office tied to those corporate campuses, luxury multifamily built to house the workforce those campuses brought in, and healthcare-anchored medical office near the city's hospital systems make up most of the institutional-grade product on the market. Retail along Preston Road and the Dallas North Tollway rounds out the mix as a more conventional NNN option. Land basis in the Legacy corridor runs higher than almost anywhere else in the metro, which changes how far exchange equity stretches and how a buyer should think about cap rate expectations before identifying a Plano asset.</p>` },
      { heading: `Class A Office Tied to the Legacy West Corporate Campuses`, html: `<p>Toyota's North American headquarters, JPMorgan Chase's regional campus, and other corporate relocations built out a concentration of Class A office space in and around Legacy West and Legacy Business Park, and that product tends to carry longer initial lease terms with corporate credit behind them. The reduction in per-employee office space that followed the shift to hybrid work has left some of this stock carrying more vacant floors than the headline occupancy figure suggests, so a buyer should ask for actual space utilization data in addition to the signed lease roster before underwriting future renewal probability. Parking ratio and proximity to the DART rail extension also affect how a given building competes for tenants inside this specific corridor.</p>` },
      { heading: `Luxury Multifamily Serving the Legacy and Granite Park Workforce`, html: `<p>Multifamily product built near Legacy West and Granite Park generally targets the professional workforce employed at the surrounding corporate campuses, which supports higher average rents than most other Plano submarkets but also ties occupancy more closely to the health of those same employers. A buyer should review employer concentration in the resident base where that data is available, since a single large employer reducing headcount can move occupancy at a property built primarily to serve that workforce. The high land basis across this corridor also means going-in cap rates here typically run lower than in an older, less corporate-dependent Plano neighborhood.</p>` },
      { heading: `Healthcare-Anchored Medical Office Near Plano's Hospital Systems`, html: `<p>Medical office building around Baylor Scott and White, Medical City Plano, and Children's Health draws physician groups and outpatient service tenants who typically sign longer leases because of buildout cost, giving this asset class a more stable renewal profile than the corporate office product elsewhere in the city. A diligence file for Plano medical office replacement property typically includes:</p><ul><li>Tenant improvement allowance history and remaining lease term</li><li>Hospital system affiliation or referral relationship, if any</li><li>Parking ratio relative to patient volume</li><li>Certificate of occupancy and use restrictions</li><li>Phase I environmental site assessment</li><li>Tenant estoppel certificates</li></ul><p>Confirming whether a tenant's lease includes a hospital system referral relationship is worth the extra step, since that relationship can materially affect renewal likelihood beyond what the lease document alone shows.</p>` },
      { heading: `Identification Timing in a High-Land-Basis Suburb`, html: `<p>Because Plano's Legacy-corridor land basis runs high relative to the rest of the metro, exchangers moving substantial relinquished-property proceeds here often need to identify a mix of asset types under the 200% rule to place all the exchange equity within the 45-day window, rather than relying on a single large office or multifamily candidate. Naming a healthcare-anchored medical office building alongside a Legacy-area multifamily candidate gives an exchanger room to compare final underwriting numbers before the identification period closes, as long as the combined identified value stays inside the 200% threshold.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Plano Acquisitions`, html: `<p>Lenders financing Plano office acquisitions have grown more attentive to space utilization data since the shift toward hybrid work, and providing actual occupancy and utilization figures alongside the signed lease roster tends to shorten underwriting on Legacy-corridor office deals. The qualified intermediary holds exchange proceeds throughout and directs them to the closing table once the purchase is ready to fund; this describes process and coordination only, and Plano exchangers should confirm tax treatment with their own advisor before closing.</p>` },
    ],
    faqs: [
      { question: `Why does Plano office space sometimes show lower actual utilization than its stated occupancy?`, answer: `The shift toward hybrid work reduced per-employee space needs at several Legacy-corridor corporate campuses, leaving signed leases in place even where floors sit partly empty. Ask for utilization data alongside the lease roster before underwriting renewal probability.` },
      { question: `Does Legacy-area multifamily carry more concentration risk than an older Plano property?`, answer: `It can, since occupancy ties more closely to the health of the corporate employers whose workforce the property was built to serve. Reviewing employer concentration in the resident base, where available, is a reasonable diligence step.` },
      { question: `What makes Plano medical office a more stable replacement property type?`, answer: `Physician and outpatient tenants near Plano's hospital systems typically sign longer leases because of buildout cost, and a hospital system referral relationship, where one exists, can further support renewal likelihood.` },
      { question: `Why would I identify more than one asset type in Plano under the 200% rule?`, answer: `High land basis in the Legacy corridor means a single large candidate may not use all available exchange equity efficiently. Naming a mix of asset types gives room to compare final underwriting before the 45-day window closes.` },
      { question: `Do lenders ask for anything unusual on Legacy-corridor office deals?`, answer: `Many now request actual space utilization figures in addition to the signed lease roster. The qualified intermediary still holds and directs exchange funds; this is process description only, and investors should confirm tax treatment with their own advisor.` },
    ],
  },
  "frisco-tx": {
    sections: [
      { heading: null, html: `<p>Frisco has added commercial product faster than almost any other suburb in the metro, and that pace shows up directly in what an exchanger finds available. The Star, developed alongside the Dallas Cowboys' headquarters and practice facility, and Frisco Station nearby carry a mix of corporate office, hospitality, and entertainment retail. PGA Frisco at Fields Ranch, home to the PGA of America's relocated headquarters, has pulled golf-tourism hospitality and supporting retail into the western part of the city. The Stonebriar corridor holds more conventional regional retail and NNN pad sites. Land basis across Frisco runs high given how quickly rooftops have filled in, which changes how far exchange equity stretches compared to an older, more built-out suburb, and often means an exchanger moving proceeds from a lower-basis market elsewhere finds fewer square feet or units purchasable per dollar here than the headline growth story might suggest.</p>` },
      { heading: `The Star and Frisco Station: Office, Hospitality, and Entertainment Retail`, html: `<p>The Star's mixed-use development, built alongside the Cowboys' headquarters and indoor practice facility, supports hotel and entertainment-retail tenants whose demand ties partly to team activity and public events held there, while Frisco Station nearby has built out more conventional Class A office aimed at corporate relocations. A buyer should separate these two demand drivers when reviewing a listing in this area, since a hotel tied to team-related event traffic will show a different seasonal pattern than a straight corporate office building leased to a single long-term tenant. The office side of Frisco Station also draws a distinct tenant profile, generally corporate users seeking newer space without a direct tie to the entertainment calendar next door.</p>` },
      { heading: `PGA Frisco and Fields Ranch Hospitality Demand`, html: `<p>The PGA of America's relocated headquarters and the two championship golf courses at Fields Ranch have pulled golf-tourism hospitality, corporate meeting space, and supporting retail into western Frisco, and much of this product is still working through initial lease-up rather than sitting on a long trailing operating history. A buyer should ask for whatever trailing data does exist and treat any pro forma projection with real scrutiny, since a newly opened hospitality asset in a growth corridor can carry more optimistic assumptions than the actual booking pace supports.</p>` },
      { heading: `Stonebriar Retail and NNN Pad Sites`, html: `<p>The Stonebriar corridor holds Frisco's more conventional regional retail, including mall-adjacent big-box space and freestanding NNN pad sites leased to national tenants, and this product generally trades on more familiar underwriting than the newer mixed-use development elsewhere in the city. A diligence file for Stonebriar-area NNN replacement property typically includes:</p><ul><li>Remaining primary lease term and renewal option structure</li><li>Corporate guaranty versus franchisee guaranty on the lease</li><li>Co-tenancy clause review against current mall or center occupancy</li><li>Reciprocal easement agreement terms for shared parking and access</li><li>Phase I environmental site assessment</li><li>Tenant estoppel certificate</li></ul><p>Reviewing the co-tenancy clause against actual current occupancy at the surrounding center is worth doing directly rather than assuming a national-brand tenant makes the lease self-sustaining regardless of nearby vacancy.</p>` },
      { heading: `Identification Timing in a High-Growth, High-Land-Basis Suburb`, html: `<p>Because Frisco's land basis has climbed quickly, exchangers moving proceeds here sometimes need to identify more than one candidate under the 200% rule to place all available equity, particularly when pairing a stabilized Stonebriar NNN asset with a newer, less-proven property near The Star or PGA Frisco. Naming both keeps the stabilized asset available as a fallback if lease-up data on the newer property does not hold up once the 45-day identification window closes.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Newer Frisco Product`, html: `<p>Lenders financing newer Frisco hospitality or mixed-use product near The Star or PGA Frisco often request more conservative underwriting assumptions than they would for a stabilized Stonebriar retail asset, given the shorter operating history involved, and surfacing that expectation with the lender early helps keep the loan on pace for the 180-day closing deadline. The qualified intermediary holds exchange proceeds throughout this process and directs them to closing; this describes process and coordination only, and Frisco exchangers should confirm tax treatment with their own advisor.</p>` },
    ],
    faqs: [
      { question: `How should I think about hospitality demand at The Star versus Frisco Station?`, answer: `Separate the two. Hotel demand at The Star ties partly to team activity and public events, while Frisco Station's office product targets corporate relocations with a more conventional lease pattern. Underwrite each on its own demand driver.` },
      { question: `Is PGA Frisco hospitality product a stabilized asset class yet?`, answer: `Much of it is still working through initial lease-up. Ask for whatever trailing data exists and scrutinize any pro forma projection rather than relying on booking assumptions alone.` },
      { question: `What should I check on a Stonebriar-area NNN retail lease?`, answer: `Review the co-tenancy clause against actual current occupancy at the surrounding center, and confirm whether the lease carries a corporate or franchisee guaranty, since these affect renewal risk differently.` },
      { question: `Why would I identify more than one property in a fast-growing suburb like Frisco?`, answer: `High land basis here means a single candidate may not use available exchange equity efficiently. Pairing a stabilized Stonebriar asset with a newer property near The Star or PGA Frisco under the 200% rule keeps a fallback option available.` },
      { question: `Do lenders underwrite newer Frisco product more conservatively?`, answer: `Often, yes, given the shorter operating history on recently opened hospitality and mixed-use assets. The qualified intermediary still holds and directs exchange funds; this is process description only, and investors should confirm tax treatment with their own advisor.` },
    ],
  },
  "irving-tx": {
    sections: [
      { heading: null, html: `<p>Irving's commercial base splits along a few clear lines. Las Colinas holds a mix of aging Class B office towers and newer, renovated Class A product, much of it clustered around the canals and the Toyota Music Factory entertainment district. Proximity to DFW International Airport, whose northwest runways sit inside Irving's city limits, supports a heavy concentration of hotel and hospitality product tied to both business travel and the Irving Convention Center's event calendar. Industrial and flex buildings along State Highway 183 and Belt Line Road round out the base, serving distribution tenants who value the airport access. An exchanger identifying Irving replacement property is often choosing between office vintage, hospitality performance, and industrial lease structure, and each carries a different diligence path.</p>` },
      { heading: `Las Colinas Office Towers: Class A Renovation Versus Class B Value-Add`, html: `<p>Las Colinas was built out as an urban center decades ago, and the office towers there now split fairly clearly between renovated or newer Class A buildings, which trade closer to institutional pricing, and older Class B stock, which typically trades at value-add pricing tied to lease-up risk rather than in-place income alone. A buyer looking at Class B product should ask for a specific capital plan and cost estimate for common-area and system upgrades before assuming the going-in cap rate reflects the true cost of holding the asset, since deferred maintenance on a decades-old tower can be substantial. Proximity to the DART Orange Line's Urban Center and Las Colinas stations also affects leasing velocity on both tiers of product.</p>` },
      { heading: `Hospitality Demand Tied to DFW Airport and the Convention Center`, html: `<p>Hotel product near DFW Airport and the Irving Convention Center draws both business travelers and event-driven group demand, and occupancy at these properties tends to move with the airport's business travel patterns and the convention calendar more than with any broader Irving economic trend. A buyer should review trailing revenue per available room across a full year, separating group-driven weeks from typical business-travel weeks, since a hotel's mix of those two demand types affects how sensitive future performance will be to a slower convention calendar.</p>` },
      { heading: `Industrial and Flex Along State Highway 183 and Belt Line Road`, html: `<p>Industrial and flex buildings along SH 183 and Belt Line Road serve distribution and light-assembly tenants who specifically value the short drive to DFW Airport's cargo facilities, and lease terms here run from single-tenant long-term agreements to shorter multi-tenant flex leases. A diligence file for this corridor typically includes:</p><ul><li>Clear height and dock door count relative to tenant requirements</li><li>Trailer parking and truck court capacity</li><li>Remaining lease term against tenant's stated buildout cost</li><li>Rail or airport-cargo access confirmation, if claimed by the listing</li><li>Phase I environmental site assessment</li><li>Tenant estoppel certificates</li></ul><p>Confirming actual cargo or logistics access rather than relying on a general claim of airport proximity is worth the extra step, since not every building along this corridor has the same practical access.</p>` },
      { heading: `Identification Timing Across Office, Hospitality, and Industrial`, html: `<p>Because Irving spans such different asset classes within one submarket, exchangers here sometimes identify a Las Colinas office candidate alongside a Belt Line industrial building under the three-property rule, keeping both open while final underwriting on hotel-adjacent risk or office capital needs gets finished within the 45-day identification window. Naming both candidates costs nothing extra as long as either could realistically close, and the identification letter should describe each with enough specificity that a reviewer could locate the exact property.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Airport-Proximate Assets`, html: `<p>Lenders financing Irving hospitality acquisitions typically request a longer trailing operating history than they would for a straight office or industrial deal, given how sensitive hotel performance is to the convention and travel calendar, and getting that operating history assembled early helps keep the loan process on pace with the 180-day closing deadline. The qualified intermediary holds exchange proceeds throughout this process and releases them at closing; this describes process and coordination only, and Irving exchangers should confirm tax treatment with their own advisor.</p>` },
    ],
    faqs: [
      { question: `How do I tell whether a Las Colinas office tower is priced as Class A or value-add Class B?`, answer: `Ask for a specific capital plan and cost estimate for common-area and system upgrades rather than relying on the stated cap rate alone, since deferred maintenance on older Las Colinas towers can be significant.` },
      { question: `Why does hotel performance near DFW Airport vary so much from month to month?`, answer: `Occupancy and rate move with business travel patterns and the Irving Convention Center's event calendar. Review a full year of trailing revenue per available room, separating group weeks from typical business-travel weeks.` },
      { question: `What should I confirm before identifying an industrial building along Belt Line Road?`, answer: `Confirm actual cargo or logistics access rather than a general claim of airport proximity, and check clear height, dock door count, and trailer parking against what the current or prospective tenant requires.` },
      { question: `Can I identify an office property and an industrial property in Irving at the same time?`, answer: `Yes, many exchangers name both under the three-property rule to keep options open while underwriting on either candidate finishes, as long as either property could realistically close within the exchange period.` },
      { question: `Do lenders ask for more history on Irving hotel deals than on office or industrial?`, answer: `Typically yes, given how sensitive hospitality performance is to the travel and convention calendar. The qualified intermediary still holds and directs exchange funds; this is process description only, and investors should confirm tax treatment with their own advisor.` },
    ],
  },
  "arlington-tx": {
    sections: [
      { heading: null, html: `<p>Arlington's commercial base carries the fingerprint of AT&T Stadium, Globe Life Field, and the Texas Live! entertainment district, all clustered together and all driving hospitality and mixed-use demand that behaves differently than a typical suburban hotel or retail market. The University of Texas at Arlington supports a separate student-housing base with its own leasing calendar, and the older Great Southwest Industrial District along Arlington's western edge holds industrial stock that has been trading and repositioning for decades. Retail along Cooper Street and the I-30 corridor serves the resident population rather than the event crowd, with grocery-anchored centers and freestanding pad sites that lease on a more conventional, steady basis than anything tied to the stadium calendar. An exchanger looking at Arlington replacement property needs to know which of these demand drivers a given asset actually depends on before assuming a stabilized rent roll will hold, since a retail center a few miles from the entertainment district can carry an entirely different risk profile than one built into it.</p>` },
      { heading: `Entertainment-District Hospitality Around the Stadiums`, html: `<p>Hotel and hospitality product near AT&T Stadium, Globe Life Field, and Texas Live! draws heavy event-driven demand tied to the Cowboys and Rangers schedules, concerts, and conventions, and that demand is genuinely seasonal rather than steady. A buyer should review trailing revenue per available room broken out by month across a full year, comparing game-week and concert-week performance against the quieter stretches of the calendar, since underwriting off a peak month alone will overstate what the asset produces on average. Mixed-use retail and restaurant space built into the Texas Live! development carries a similar event-driven pattern.</p>` },
      { heading: `Student Housing Serving the University of Texas at Arlington`, html: `<p>Multifamily and purpose-built student housing near UT Arlington leases on an academic-year cycle rather than the calendar-year pattern typical of conventional apartments, with pre-leasing activity concentrated in a narrow window each spring and turnover concentrated around the fall semester start. A buyer should ask for the current pre-leasing percentage relative to the same point in the prior year rather than relying on trailing occupancy alone, since a student property can show strong trailing numbers while pre-leasing for the coming year is running behind. Distance to campus and to the shuttle routes serving it also affects leasing velocity meaningfully within this submarket, more so than in a conventional multifamily deal where commute distance rarely drives leasing decisions the same way.</p>` },
      { heading: `Great Southwest Industrial District`, html: `<p>The Great Southwest Industrial District, developed decades ago along Arlington's western edge, holds some of the oldest industrial building stock in the metro, and older clear heights and dock configurations there sometimes fall short of what a modern distribution tenant requires. A diligence file for Great Southwest replacement property typically includes:</p><ul><li>Clear height and dock door count against current tenant or market requirements</li><li>Roof and structural condition report on older buildings</li><li>Rail spur access confirmation, where claimed</li><li>Remaining lease term against tenant buildout cost</li><li>Phase I environmental site assessment given the district's manufacturing history</li><li>Tenant estoppel certificates</li></ul><p>A Phase I environmental review is worth particular attention in this district given its long manufacturing and warehousing history, rather than treating it as a formality.</p>` },
      { heading: `Identification Timing for Event-Driven and Academic-Calendar Assets`, html: `<p>Because both entertainment-district hospitality and UT Arlington student housing move on their own calendars rather than a conventional lease cycle, exchangers often pair one of those assets with a more conventional Great Southwest industrial building under the three-property or 200% rule, giving themselves a stabilized fallback candidate while trailing performance data on the calendar-driven asset gets fully reviewed inside the 45-day identification window.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Calendar-Driven Assets`, html: `<p>Lenders financing entertainment-district hospitality or student housing in Arlington typically ask for a longer trailing operating history than a straight industrial or conventional multifamily deal would require, precisely because both asset types carry calendar-driven swings. Assembling that history before submitting the loan application tends to keep underwriting on pace with the 180-day closing deadline. The qualified intermediary holds exchange proceeds throughout and directs them to closing; this describes process and coordination only, and Arlington exchangers should confirm tax treatment with their own advisor.</p>` },
    ],
    faqs: [
      { question: `How seasonal is hotel performance near AT&T Stadium and Globe Life Field?`, answer: `Quite seasonal. Review trailing revenue per available room broken out by month across a full year, comparing game-week and concert-week performance against quieter stretches, rather than underwriting off a peak month.` },
      { question: `What should I check before identifying student housing near UT Arlington?`, answer: `Ask for the current pre-leasing percentage compared to the same point last year, since trailing occupancy alone can look strong even when pre-leasing for the coming academic year is running behind.` },
      { question: `Are Great Southwest Industrial District buildings suited to modern distribution tenants?`, answer: `Some are, but older clear heights and dock configurations in this decades-old district can fall short of current requirements. Confirm clear height and dock count against the tenant's actual needs before identification.` },
      { question: `Why would I pair a stadium-area hotel with an industrial building in the same exchange?`, answer: `Many exchangers do this under the three-property or 200% rule, keeping the industrial building as a stabilized fallback while trailing hospitality performance data gets fully reviewed within the 45-day window.` },
      { question: `Do lenders need more history for Arlington hospitality or student housing deals?`, answer: `Typically yes, given the calendar-driven swings in both asset types. The qualified intermediary still holds and directs exchange funds; this is process description only, and investors should confirm tax treatment with their own advisor.` },
    ],
  },
  "addison-tx": {
    sections: [
      { heading: null, html: `<p>Addison packs an outsized commercial footprint into one of the smallest cities in Texas by land area, and the daytime population from its office towers and restaurant corridor barely resembles the number of people who actually live there. An owner selling Addison property is almost always dealing with corporate office near Addison Circle, a restaurant or retail pad along Belt Line Road, or land near Addison Airport, and each of those has a different replacement search attached to it.</p>` },
      { heading: `Reading Addison's Compressed Commercial Mix`, html: `<p>Because the city is so small geographically, its commercial categories sit close together but do not behave the same way underwriting-wise. The stock an Addison seller is typically choosing among includes:</p><ul><li>Corporate office towers in and around Addison Circle</li><li>Restaurant and retail pads along the Belt Line Road entertainment corridor</li><li>Light industrial and hangar-adjacent land near Addison Airport</li><li>Mixed-use residential-over-retail buildings tied to the Addison Circle district</li><li>DST interests for owners exiting active office or restaurant-pad management</li></ul>` },
      { heading: `Identification Strategy for a Dense, Small-Footprint Market`, html: `<p>An owner trading one Belt Line restaurant pad for another can often stay within the three-property rule, since comparable pads are not hard to compare once a short list is drawn up. Someone exiting corporate office and considering a mix of restaurant, retail, and DST candidates typically needs the 200 percent rule, because office and restaurant income behave differently enough that a narrow three-property list rarely captures the right range of options.</p>` },
      { heading: `What Diligence Misses in a Dense Corridor Like This`, html: `<p>Parking is tighter in Addison than in most surrounding suburbs, and a buyer should confirm actual available spaces against the lease requirements of any tenant rather than trusting a site plan drawn years ago. Restaurant pads along Belt Line Road turn over more often than the rent roll suggests, since the restaurant category carries more operational risk than a standard retail tenant. Office towers near Addison Circle should be checked for tenant concentration, because a building concentrated in one or two large tenants carries more rollover exposure than the occupancy rate alone implies. That concentration risk is worth pricing into the offer rather than discovering it only after a large tenant gives notice. Mixed-use buildings that combine residential units above ground-floor retail also need a separate look at the residential component's occupancy and management arrangement, since that piece of the building behaves nothing like the commercial space beneath it.</p>` },
      { heading: `Coordinating Lenders Around Addison's Airport-Adjacent Land`, html: `<p>Financing land near Addison Airport requires confirming FAA height and use restrictions before a lender will commit, since those restrictions can limit what can actually be built regardless of the zoning designation. That review should start the moment the property is identified, not after the qualified intermediary asks for a closing date, because airport-related approvals can take longer than a standard commercial loan underwriting. A buyer should also ask whether any hangar or aviation-related easements run with the land, since those can restrict future use even after the FAA height review clears.</p>` },
      { heading: `What a Clean Addison Exchange Looks Like`, html: `<p>The Addison investors who move efficiently confirm parking, tenant concentration, and airport-related restrictions early rather than assuming a small, familiar city means fewer surprises, and they size their identification list to match whether they are staying inside one property type or spreading across office, restaurant, and retail categories. Given how compact the city is, a buyer touring candidates in a single afternoon should still treat each property on its own operational merits rather than assuming geographic closeness means comparable underwriting, since a restaurant pad three blocks from a corporate tower behaves nothing like the tower itself, and lumping the two together in an investment thesis is a mistake worth avoiding from the start.</p>` },
    ],
    faqs: [
      { question: `Why does parking matter so much for Addison retail and restaurant deals?`, answer: `Addison's compact footprint means parking ratios are tighter than in surrounding suburbs. A buyer should verify actual available spaces against current tenant lease requirements rather than relying on an older site plan.` },
      { question: `Are restaurant pads along Belt Line Road a stable 1031 replacement?`, answer: `They can generate steady income, but the restaurant category turns over more frequently than standard retail, so a buyer should weigh operational risk alongside the current rent roll rather than treating restaurant income as automatically comparable to a net lease retail tenant. A concept that has changed hands more than once at the same pad is worth extra scrutiny before assuming the location alone guarantees demand.` },
      { question: `What restrictions apply to land near Addison Airport?`, answer: `FAA height and use restrictions can limit development regardless of the underlying zoning designation, so a buyer should confirm those restrictions before relying on the property's stated development potential in any offer or pro forma.` },
      { question: `Should I use the three-property rule for an Addison office-to-office trade?`, answer: `It often works for a straightforward office replacement. An investor diversifying out of office into restaurant or retail candidates typically needs the 200 percent rule to keep enough comparable options open before the identification deadline, since those categories rarely narrow to three clean choices on the same timeline.` },
      { question: `Can 1031 Exchange Dallas confirm my Addison property qualifies for an exchange?`, answer: `No. This service coordinates planning, property identification, and communication among the investor's advisors. Whether a specific transaction and property qualify is a determination made by the investor's CPA, tax attorney, and qualified intermediary.` },
    ],
  },
  "richardson-tx": {
    sections: [
      { heading: null, html: `<p>Richardson built its commercial identity around the Telecom Corridor, the stretch of office and flex space along Central Expressway that once housed Texas Instruments, Nortel, and a long list of telecommunications tenants, and a meaningful share of that stock is now aging past what a modern tenant wants without capital investment. CityLine, the mixed-use development that grew up around State Farm's regional campus, represents the newer end of the spectrum, with adjacent multifamily and retail built to serve that workforce. The University of Texas at Dallas supports its own pocket of student-driven multifamily and research-adjacent flex space nearby. An exchanger sourcing Richardson replacement property is often choosing between a stabilized CityLine-area asset and a value-add Telecom Corridor building, and those two paths carry different capital assumptions and different comparable-sales pools to draw on when setting a purchase price.</p>` },
      { heading: `Telecom Corridor Office and Flex: Functional Obsolescence and Redevelopment Risk`, html: `<p>Much of the office and flex stock along the Telecom Corridor was purpose-built for a telecommunications tenant base that has largely moved on, and buildings from that era sometimes carry floor plates, ceiling heights, or power capacity that do not suit a modern office or light-industrial tenant without renovation. A buyer should request a specific capital plan and cost estimate for any repositioning, rather than assuming the current low basis alone makes the deal attractive, since the cost to bring an obsolete telecom-era building up to current tenant expectations can offset much of that basis advantage. Some owners along this corridor have pursued a change of use entirely, converting older flex buildings to self-storage or last-mile distribution rather than repositioning them as office, and a buyer should ask which path the current owner's capital work actually supports before assuming a straight office renovation is the only option.</p>` },
      { heading: `CityLine and the State Farm Regional Campus`, html: `<p>CityLine's mixed-use development, developed alongside State Farm's large regional campus, has drawn newer multifamily, retail, and hotel product designed to serve that workforce, and this asset class generally carries more conventional, institutional-grade underwriting than the older Telecom Corridor stock. A buyer should still review employer concentration for any CityLine-area multifamily property, since occupancy here ties meaningfully to a single large corporate campus rather than a broad, diversified employment base. Retail and hotel space built into the same development generally serves that same corporate population, which means weekday demand at a CityLine restaurant or hotel can look considerably different from weekend demand, and a buyer should ask for a day-of-week revenue breakdown rather than a single blended average.</p>` },
      { heading: `UT Dallas-Adjacent Student Housing and Research Flex`, html: `<p>Multifamily near the University of Texas at Dallas leases on an academic calendar rather than a conventional year-round pattern, and nearby flex space sometimes serves university-adjacent research tenants whose lease terms can differ meaningfully from a standard industrial tenant. A diligence file for UT Dallas-adjacent replacement property typically includes:</p><ul><li>Pre-leasing percentage compared to the same point in the prior year</li><li>Lease term and use restrictions on any research-adjacent flex tenant</li><li>Parking allocation relative to student or research-staff population</li><li>Remaining lease term against tenant buildout cost</li><li>Phase I environmental site assessment</li><li>Tenant estoppel certificates</li></ul><p>Confirming pre-leasing pace against the prior year is worth doing directly for student-oriented product, since trailing occupancy alone can understate a coming shortfall.</p>` },
      { heading: `Identification Timing Between Value-Add and Stabilized Richardson Product`, html: `<p>Exchangers weighing a Telecom Corridor value-add candidate against a stabilized CityLine-area asset often name both under the three-property or 200% rule, keeping the stabilized property as the frontrunner while a contractor or engineer finishes the capital-plan estimate for the older building within the 45-day identification window. Naming the value-add candidate as a backup costs nothing extra as long as its identified value, combined with the frontrunner, stays within the applicable threshold.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Value-Add Telecom Corridor Deals`, html: `<p>Lenders financing a Telecom Corridor repositioning typically request the capital plan and renovation budget up front, treating the deal more like a value-add underwrite than a straight income acquisition, and surfacing that plan early tends to keep the loan process aligned with the 180-day closing deadline. The qualified intermediary holds exchange proceeds throughout and directs them to the closing table; this describes process and coordination only, and Richardson exchangers should confirm tax treatment with their own advisor.</p>` },
    ],
    faqs: [
      { question: `Why does Telecom Corridor office space sometimes trade at a lower basis than the rest of Richardson?`, answer: `Much of it was purpose-built for a telecommunications tenant base that has largely moved on, and floor plates, ceiling heights, or power capacity from that era can require renovation to suit a modern tenant, which offsets some of the basis advantage.` },
      { question: `Does CityLine multifamily carry employer concentration risk?`, answer: `Some, since occupancy ties meaningfully to the State Farm regional campus rather than a broad, diversified employment base. Reviewing employer concentration is a reasonable diligence step before identification.` },
      { question: `What should I check before identifying student housing near UT Dallas?`, answer: `Compare the current pre-leasing percentage to the same point in the prior year, since trailing occupancy alone can understate a coming shortfall in a property that leases on an academic calendar.` },
      { question: `Why would I identify a value-add Telecom Corridor building alongside a stabilized CityLine asset?`, answer: `Many exchangers do this under the three-property or 200% rule, keeping the stabilized property as the frontrunner while a capital-plan estimate for the older building gets finished within the 45-day window.` },
      { question: `Do lenders underwrite Telecom Corridor deals differently than CityLine acquisitions?`, answer: `Often, yes, treating a Telecom Corridor repositioning more like a value-add underwrite and requesting the capital plan up front. The qualified intermediary still holds and directs exchange funds; this is process description only, and investors should confirm tax treatment with their own advisor.` },
    ],
  },
  "carrollton-tx": {
    sections: [
      { heading: null, html: `<p>Carrollton's most distinctive commercial feature is how much of its recent development activity clusters around DART rail access. Old Town Carrollton and the Trinity Mills area have both seen transit-oriented mixed-use redevelopment built next to their rail stations, while the older retail base near Vista Ridge Mall has been working through repositioning as large-format anchor space has changed hands. Industrial and flex buildings along Sandy Lake Road and Belt Line Road, close enough to Addison Airport to draw tenants who value that proximity, round out the base. An exchanger sourcing Carrollton replacement property is often choosing between a newer transit-oriented asset and an older retail or industrial building further along in its repositioning, and the two paths differ meaningfully in how much operating history exists to underwrite against.</p>` },
      { heading: `Transit-Oriented Redevelopment at Old Town and Trinity Mills`, html: `<p>Old Town Carrollton and the Trinity Mills area have both attracted mixed-use redevelopment built specifically next to their DART rail stations, and a meaningful share of this product is either newly delivered or still working through lease-up rather than sitting on years of stabilized operating history. A buyer should ask for whatever trailing leasing data exists and treat the pro forma with real scrutiny, comparing the property's actual absorption pace against the broader pattern of transit-oriented development elsewhere in the corridor rather than assuming it will lease at the pace projected. Ground-floor retail built into these transit-oriented projects generally depends on foot traffic from residents and rail commuters alike, so a buyer should ask how much of that traffic is already established versus projected to arrive once nearby residential phases finish leasing up.</p>` },
      { heading: `Industrial and Flex Along Sandy Lake and Belt Line, Near Addison Airport`, html: `<p>Industrial and flex buildings along Sandy Lake Road and Belt Line Road serve distribution and light-assembly tenants, and proximity to Addison Airport draws some tenants specifically for that access, though not every building along this corridor actually benefits from it. A buyer should confirm a tenant's stated reason for the location rather than assuming airport proximity adds value to every building in the area, and should review clear height and dock configuration against what a modern flex tenant expects. Several buildings in this corridor were originally built for a single long-term tenant and have since been subdivided for multiple smaller users, and a buyer should confirm that utility metering and access were properly separated during that subdivision rather than assuming the current rent roll reflects a clean, fully independent set of suites.</p>` },
      { heading: `Vista Ridge-Area Retail Repositioning`, html: `<p>Retail near Vista Ridge Mall has been working through a repositioning cycle as large-format anchor space has changed hands and, in some cases, been subdivided or converted to other uses, and this creates both opportunity and added diligence work for a buyer identifying replacement property in the area. A diligence file for Vista Ridge-area retail typically includes:</p><ul><li>Anchor tenant status and any pending lease changes</li><li>Co-tenancy clause review against current center occupancy</li><li>Remaining primary lease term and renewal option structure</li><li>Reciprocal easement agreement terms for shared parking and access</li><li>Phase I environmental site assessment</li><li>Tenant estoppel certificates</li></ul><p>Confirming the status of the anchor tenant specifically, rather than relying on the property's historical mall affiliation, is worth doing directly given how much repositioning activity has moved through this corridor.</p>` },
      { heading: `Identification Timing Between Transit-Oriented and Legacy Product`, html: `<p>Exchangers weighing a newer transit-oriented Old Town or Trinity Mills property against a more established Sandy Lake industrial building or a repositioned Vista Ridge-area retail asset often name more than one candidate under the 200% rule, keeping a better-documented property available while lease-up data on the newer transit-oriented asset gets fully reviewed inside the 45-day identification window.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Transit-Oriented Product`, html: `<p>Lenders financing a newer transit-oriented acquisition in Carrollton typically request more conservative absorption assumptions than they would for a stabilized industrial or established retail deal, given the shorter operating history involved, and surfacing that expectation early helps keep the loan process aligned with the 180-day closing deadline. The qualified intermediary holds exchange proceeds throughout this process and directs them to closing; this describes process and coordination only, and Carrollton exchangers should confirm tax treatment with their own advisor.</p>` },
    ],
    faqs: [
      { question: `Is transit-oriented development near Old Town Carrollton or Trinity Mills already stabilized?`, answer: `Much of it is newly delivered or still in lease-up. Ask for whatever trailing leasing data exists and compare actual absorption against the broader transit-oriented development pattern rather than trusting the pro forma alone.` },
      { question: `Does every industrial building near Sandy Lake Road benefit from Addison Airport proximity?`, answer: `Not necessarily. Confirm a tenant's stated reason for the location rather than assuming airport proximity adds value to every building along that corridor.` },
      { question: `What should I check before identifying Vista Ridge-area retail?`, answer: `Confirm the current status of the anchor tenant specifically, rather than relying on the property's historical mall affiliation, given how much repositioning activity has moved through this corridor.` },
      { question: `Why would I identify more than one property type in Carrollton?`, answer: `Many exchangers name a better-documented industrial or established retail candidate under the 200% rule alongside a newer transit-oriented property, keeping options open while lease-up data on the newer asset gets reviewed within the 45-day window.` },
      { question: `Do lenders treat transit-oriented Carrollton deals differently than a stabilized industrial acquisition?`, answer: `Often, yes, applying more conservative absorption assumptions given the shorter operating history. The qualified intermediary still holds and directs exchange funds; this is process description only, and investors should confirm tax treatment with their own advisor.` },
    ],
  },
  "mckinney-tx": {
    sections: [
      { heading: null, html: `<p>McKinney has grown north along US-75 and State Highway 121 faster than its commercial stock has fully caught up, which means an exchanger sourcing replacement property here finds a mix of long-established assets and product still proving itself. The historic downtown square holds adaptive-reuse retail and restaurant space around the courthouse, Craig Ranch has built out a medical office and corporate campus north of downtown, and McKinney National Airport supports a smaller but real base of aviation-related commercial property. Self-storage and neighborhood retail elsewhere in the city have generally tracked the pace of new rooftops rather than run ahead of it. Fewer of these assets have traded multiple times compared with an older Dallas suburb, so comparable sales data can be thinner than an exchanger might expect, and pricing a property here sometimes requires leaning on nearby Collin County suburbs for reference points rather than pure McKinney-only sales history.</p>` },
      { heading: `Downtown McKinney Square Adaptive Reuse`, html: `<p>The buildings ringing the historic courthouse square have largely been repositioned into restaurant, boutique retail, and small-office space, and many of these structures predate modern building codes, which means mechanical, electrical, and fire-suppression upgrades are common line items on a recent capital improvement history. A buyer should request whatever permit history exists for a specific building before assuming current systems meet code for the intended use, since a change in tenant type inside one of these older structures can trigger a more extensive upgrade requirement than a newer building would face.</p>` },
      { heading: `Craig Ranch Medical Office and Corporate Campus`, html: `<p>Craig Ranch has developed a medical office and corporate campus base north of downtown, anchored in part by hospital-system-affiliated outpatient facilities, and this product generally carries longer lease terms and more institutional underwriting than the older downtown stock. A buyer should confirm whether a given building's anchor tenant carries a hospital system affiliation, since that relationship can support renewal probability beyond what the lease term alone indicates, and should review parking ratio relative to patient volume for any outpatient-facing building.</p>` },
      { heading: `Aviation Property Near McKinney National Airport`, html: `<p>McKinney National Airport supports a smaller commercial category serving corporate and general aviation, including hangar space and fixed-base-operator facilities, and this asset class carries diligence requirements that look nothing like a standard office or retail acquisition. Demand at this airport has grown alongside the broader business-aviation activity moving north out of the Dallas core. A diligence file for airport-adjacent aviation replacement property typically includes:</p><ul><li>Airport authority ground lease terms and remaining lease years</li><li>FBO or sublease rights tied to the hangar or facility</li><li>Fuel storage environmental compliance review, where applicable</li><li>Hangar door clearance and taxiway access confirmation</li><li>Title and easement review specific to the airport authority's land</li><li>Tenant estoppel certificate</li></ul><p>Confirming remaining ground lease years is especially important with airport authority land, since financing terms and resale value both depend heavily on how much lease term remains.</p>` },
      { heading: `Identification Timing in a Submarket With Thinner Trading History`, html: `<p>Because McKinney has less trading history than an older, more built-out suburb, especially for newer product tied to residential growth like self-storage or neighborhood retail, exchangers sourcing here often name a downtown or Craig Ranch candidate with more established comparable sales alongside a newer, growth-corridor property under the three-property rule, keeping the better-documented candidate as a fallback if comparable data on the newer asset proves too thin to support the purchase price within the 45-day window.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Aviation and Specialty Property`, html: `<p>Lenders unfamiliar with airport authority ground leases sometimes need more time to underwrite an aviation-property acquisition than a conventional office or retail deal, so identifying a lender with specific experience in this asset class before formal identification helps keep the transaction on pace for the 180-day closing deadline. The qualified intermediary holds exchange proceeds throughout this process and releases them at closing; this describes process and coordination only, and McKinney exchangers should confirm tax treatment with their own advisor.</p>` },
    ],
    faqs: [
      { question: `What should I check before identifying a building on the downtown McKinney square?`, answer: `Request the permit history for the specific building, since many predate modern building codes and a change in tenant type can trigger a more extensive mechanical or fire-suppression upgrade than a newer building would require.` },
      { question: `Does a Craig Ranch medical office tenant's hospital affiliation matter for underwriting?`, answer: `Yes. A hospital system affiliation can support renewal probability beyond what the lease term alone shows, so confirming that relationship is worth the extra diligence step.` },
      { question: `What is unusual about diligence on aviation property near McKinney National Airport?`, answer: `Ground lease terms with the airport authority, FBO or sublease rights, and fuel storage environmental compliance all require review beyond a standard office or retail checklist, and remaining ground lease years affect both financing and resale value.` },
      { question: `Why is comparable sales data thinner in McKinney than in an older Dallas suburb?`, answer: `Much of the city's growth-corridor product, including self-storage and neighborhood retail, is newer and has traded fewer times, so identifying a better-documented downtown or Craig Ranch candidate as a fallback is a common approach.` },
      { question: `Do all lenders finance airport authority ground-lease property the same way?`, answer: `No. Lenders unfamiliar with this structure often need more underwriting time, so identifying a lender with specific experience before formal identification helps. The qualified intermediary still holds and directs exchange funds; this is process description only, and investors should confirm tax treatment with their own advisor.` },
    ],
  },
  "allen-tx": {
    sections: [
      { heading: null, html: `<p>Allen has grown fast enough along the busy US 75 corridor that its commercial base is still visibly catching up to the residential population feeding it, and that shows up directly in what trades here. An owner selling Allen property is usually dealing with retail near the outlet center or Watters Creek, medical office serving new residential subdivisions, or a smaller industrial or flex parcel a few blocks off the highway, and each of those has a different pool of replacement candidates.</p>` },
      { heading: `What Allen's Growth Has Actually Built`, html: `<p>Rapid residential expansion in Allen and along the US 75 corridor has pulled retail and medical office development close behind it. The categories an Allen seller typically works through include:</p><ul><li>Retail space fronting Allen Premium Outlets and the surrounding corridor</li><li>Mixed-use retail and restaurant space at Watters Creek at Montgomery Farm</li><li>Medical and dental office serving newer residential subdivisions</li><li>Flex and light-industrial buildings just off the US 75 frontage</li><li>DST interests for owners consolidating out of several smaller local holdings</li></ul>` },
      { heading: `Matching the Identification Rule to How Fast Allen Is Changing`, html: `<p>An owner trading one outlet-adjacent retail pad for a similar one nearby can generally use the three-property rule, since comparable retail along that stretch of US 75 is not hard to find. An investor exiting a smaller flex building and considering medical office, retail, or a DST as alternatives usually needs the 200 percent rule instead, because growth this fast means the comparable set keeps shifting and a locked three-property list can leave someone without a real backup.</p>` },
      { heading: `Diligence That Fast Growth Can Hide`, html: `<p>New retail and medical office construction near Allen sometimes outpaces the roads and utility capacity around it, so a buyer should confirm current traffic counts and utility service rather than relying on projections tied to the area's growth rate. Lease terms at newer retail centers here can look stronger on paper than they perform once early tenant incentives expire, and a buyer should ask what rent steps look like after any initial concession period ends. Medical office build-outs serving new subdivisions should be checked for whether the specific specialty has a realistic patient base in that immediate area, rather than leaning on the broader Allen population as justification. A pediatric dental suite and a physical therapy suite draw from very different radii, and treating them as interchangeable is a common underwriting mistake. A buyer should also ask how much of the surrounding subdivision is already built out versus still under construction, since a build-out still years from completion changes the near-term demand picture significantly.</p>` },
      { heading: `Financing in a Market That Changes This Quickly`, html: `<p>Lenders sometimes want a more current appraisal in fast-growing Allen than they would in a stabilized suburb, since comparable sales from even a year earlier can undervalue or overvalue current pricing. A buyer should confirm the appraisal's comparable set is recent before relying on it for loan sizing, and should build in extra time for that appraisal to come back if the lender flags a shortage of current comps.</p>` },
      { heading: `What a Solid Allen Exchange Looks Like`, html: `<p>The investors who handle Allen well treat its growth rate as a reason to verify rather than assume, confirming traffic, utility capacity, and appraisal currency before locking in an identification list, and they size that list to match how quickly the comparable set here can shift between the sale and the replacement closing. Given how much of Allen's retail and medical office development has happened within a fairly compressed window, a buyer benefits from asking directly how a candidate property has performed since its first full year of stabilized leasing, rather than relying on projected numbers still tied to the original pro forma or leasing brochure.</p>` },
    ],
    faqs: [
      { question: `Does Allen's rapid growth affect appraisal accuracy for a 1031 replacement?`, answer: `It can. Comparable sales even a year old may not reflect current pricing in a fast-growing corridor like this one, so a buyer should confirm the appraisal relies on recent comparables and build in extra time if the lender needs to source additional recent sales. Asking the appraiser directly which comparables they plan to use before the report is finalized can catch a mismatch early, well before the report comes back low.` },
      { question: `Are rent steps at newer Allen retail centers reliable after tenant incentives expire?`, answer: `Not always at the level shown during any initial concession period. A buyer should ask specifically what rent looks like once early incentives end rather than relying on the current in-place rate alone.` },
      { question: `Should I use the 200 percent rule for an Allen flex-to-medical-office trade?`, answer: `Often yes. Growth this fast means the comparable set of replacement candidates keeps shifting, and the 200 percent rule allows an investor to name multiple candidates across property types rather than being limited to three under the standard rule.` },
      { question: `What should I check before buying medical office near new Allen subdivisions?`, answer: `Confirm that the specific medical specialty has a realistic patient base in that immediate area rather than relying on the broader overall population growth of Allen as a whole to justify the lease terms.` },
      { question: `Can 1031 Exchange Dallas confirm my Allen property qualifies for an exchange?`, answer: `No. This service coordinates planning, property sourcing, and communication among the investor's advisors. Whether a specific transaction and property qualify is a determination made by the investor's CPA, tax attorney, and qualified intermediary.` },
    ],
  },
  "lewisville-tx": {
    sections: [
      { heading: null, html: `<p>Lewisville runs along I-35E north of Dallas, wrapped around Lewisville Lake, and the market underneath that geography splits into three fairly distinct lanes: flex and distribution space near the I-35E/Sam Rayburn Tollway interchange, retail centers working through tenant turnover around the Vista Ridge corridor, and newer mixed-use parcels tied to the Old Town Lewisville revival. A seller closing out of any one of those does not get extra days on the 45-day clock to sort out which lane the replacement belongs in.</p>` },
      { heading: `What Actually Trades in the Lewisville Corridor`, html: `<p>An investor selling Lewisville property is rarely comparing apples to apples once the search for a replacement starts. The candidates tend to fall into a short list of recognizable types:</p><ul><li>Flex and light-industrial buildings near the I-35E and Sam Rayburn Tollway (SH 121) interchange</li><li>Retail pads and strip centers around Vista Ridge working through lease rollover</li><li>Mixed-use and multifamily parcels tied to the Old Town Lewisville redevelopment push</li><li>Corporate and back-office space in the Lakepointe business park</li><li>DST interests for owners exiting active management of lake-adjacent commercial property</li></ul>` },
      { heading: `Picking an Identification Rule for a Lewisville Sale`, html: `<p>A straightforward retail-to-retail trade near Vista Ridge can often stay inside the three-property rule, since comparable centers are easy enough to line up side by side. An owner headed toward tollway-adjacent flex or industrial space usually needs more room, because that stock moves fast and a single front-runner can fall through in diligence. The 200 percent rule lets that owner name several industrial and flex candidates together without hitting a value cap, which matters more in Lewisville's tighter industrial corridor than it does in a deeper retail market.</p>` },
      { heading: `Diligence Points Lewisville Deals Get Wrong`, html: `<p>Anything near Lewisville Lake needs a real flood plain and drainage check before an investor assumes the site is buildable as shown, not an assumption carried over from the listing sheet. Older retail centers around Vista Ridge often carry deferred roof and parking lot maintenance that a seller's numbers understate, so an independent estimate matters before the identification deadline locks a buyer in. Old Town Lewisville parcels frequently come with entitlement or zoning conditions still in process, and a buyer relying on a developer's optimistic timeline for that approval is taking on more risk than the purchase price suggests. A title search that turns up an old easement tied to the property's prior use as farmland or a lakeside recreational lot is not unusual in this part of Lewisville, and it should be resolved before the identification deadline rather than left as a closing-week surprise.</p>` },
      { heading: `Getting the Lender and QI Moving on Tollway Timing`, html: `<p>Financing on flex and industrial space near the tollway needs to start earlier than a stabilized retail purchase, because underwriting on newer flex product looks different from underwriting a fifteen-year-old strip center with a known tenant roster. The qualified intermediary, lender, and title company all need the property type settled early so none of them are guessing at structure while the 45-day window burns down. A Lewisville buyer who waits until day thirty to engage a lender on an industrial deal is usually the one asking for an extension nobody can grant. Title work on Lakepointe-area parcels can also take longer than expected if the property was subdivided from a larger tract, so ordering that title commitment early keeps the closing date from sliding.</p>` },
      { heading: `What a Clean Lewisville Exchange Looks Like`, html: `<p>The Lewisville sellers who move fastest are honest early about which lane their replacement search actually belongs in, tollway-facing industrial, Vista Ridge retail, or Old Town mixed-use, and they line up diligence and financing around that lane rather than keeping every option open until week five, when there is no longer enough runway left to fix a mismatch. A short, honest conversation with the qualified intermediary in the first week about which lane the search is actually headed toward tends to save more time than a longer search that keeps every door open.</p>` },
    ],
    faqs: [
      { question: `Does proximity to Lewisville Lake create extra diligence steps?`, answer: `It can. Parcels near the lake sometimes carry flood plain or drainage restrictions that affect buildable area, so an investor should confirm that status with a survey rather than assuming the listing description is current.` },
      { question: `Why would I need the 200 percent rule for a Lewisville industrial purchase?`, answer: `Flex and industrial space near the I-35E/Sam Rayburn Tollway interchange moves quickly and a single front-runner can fall out of contract during diligence. The 200 percent rule lets an investor name several candidates at once instead of being limited to three under the standard rule.` },
      { question: `Do Old Town Lewisville redevelopment parcels qualify as 1031 replacement property?`, answer: `Real property held for investment or business use generally qualifies regardless of its redevelopment stage, but an investor should have the entitlement and zoning status confirmed independently before relying on it as part of the exchange timeline.` },
      { question: `How early should financing start on a tollway-facing flex property?`, answer: `Earlier than a stabilized retail purchase. Lender underwriting on newer flex and industrial product differs from a purchase with a known, seasoned tenant roster, so engaging a lender well before the identification deadline avoids a late scramble.` },
      { question: `Can 1031 Exchange Dallas confirm my Lewisville transaction qualifies as an exchange?`, answer: `No. This service coordinates planning, property identification, and communication among the investor's advisors. Whether a specific transaction and property qualify is a determination made by the investor's CPA, tax attorney, and qualified intermediary.` },
    ],
  },
  "flower-mound-tx": {
    sections: [
      { heading: null, html: `<p>Flower Mound sits between Lewisville Lake and Grapevine Lake in the northwest metro and has grown into an affluent, largely residential suburb with a commercial base weighted toward retail, medical office, and limited light industrial. An owner selling property here is rarely dealing with heavy industrial product, since the town's zoning has historically limited that category in favor of retail and office.</p>` },
      { heading: `Lakeside DFW and the Town's Newest Mixed-Use Retail`, html: `<p>Lakeside DFW, the town's largest mixed-use retail development, has anchored newer commercial growth along the FM 2499 corridor, drawing national retailers and restaurants that did not previously have a Flower Mound presence. An owner selling an older strip center nearby should weigh how much of their tenant base and foot traffic has shifted toward Lakeside DFW before assuming their current rent roll reflects a stable trend. Restaurant and specialty grocery tenants in particular have gravitated toward Lakeside DFW's newer buildout, and an older center competing for that same tenant category should be underwritten with realistic re-tenanting timelines rather than assuming the prior tenant's rent simply resets at renewal.</p>` },
      { heading: `Medical Office Tied to Texas Health Presbyterian Flower Mound`, html: `<p>Medical office demand in Flower Mound is closely tied to the Texas Health Presbyterian Flower Mound hospital campus, and buildings within a short distance of the campus tend to command a premium over general office space. An investor exchanging into medical office here should confirm whether tenants hold hospital system affiliation agreements, since that affiliation status affects both stability and resale value.</p>` },
      { heading: `Why Industrial Supply Stays Limited in Flower Mound`, html: `<p>Flower Mound's zoning has historically favored residential and lower-intensity commercial use over heavy industrial development, which keeps industrial and flex supply scarcer here than in neighboring Lewisville or Carrollton. An investor specifically wanting industrial replacement product usually needs to widen the search to those adjacent cities rather than expecting comparable inventory within Flower Mound itself.</p>` },
      { heading: `Identification Timing in a Restrictive-Zoning Suburb`, html: `<p>Because commercial land use is more restricted here than in surrounding suburbs, comparable Flower Mound product can be limited, and an investor targeting the town specifically often benefits from the two hundred percent rule to keep enough candidates on the list. Someone willing to include Lewisville, Highland Village, or Grapevine candidates can usually work within the three property rule instead.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Flower Mound Retail and Medical Deals`, html: `<p>Lenders financing Flower Mound retail near Lakeside DFW or medical office near the hospital campus generally look for stable, credit-quality tenants given the town's affluent demographic base, and pricing can reflect that quality premium. We coordinate documentation with the qualified intermediary early so the underwriting process keeps pace with the exchange deadlines.</p>` },
    ],
    faqs: [
      { question: `Has Lakeside DFW affected older Flower Mound retail centers?`, answer: `In many cases yes. Newer national retail and restaurant tenants have concentrated around Lakeside DFW, so a buyer evaluating an older nearby strip center should confirm whether its tenant base and foot traffic have held steady rather than assuming past performance continues unchanged.` },
      { question: `Why is medical office near Texas Health Presbyterian Flower Mound priced at a premium?`, answer: `Proximity to the hospital campus supports stronger tenant demand than general office space in the area, and buildings with tenants holding hospital system affiliation agreements typically carry added stability and resale value.` },
      { question: `Can I find industrial replacement property directly in Flower Mound?`, answer: `Supply is limited. Flower Mound's zoning has historically favored residential and lower-intensity commercial use, so investors wanting industrial product usually need to widen the search to Lewisville, Carrollton, or other neighboring cities.` },
      { question: `Should I use the three property rule for a Flower Mound-only search?`, answer: `It depends on availability. Flower Mound's limited commercial inventory often calls for the 200 percent rule, while including nearby Lewisville, Highland Village, or Grapevine candidates usually makes the three property rule practical.` },
      { question: `Can 1031 Exchange Dallas confirm my Flower Mound property qualifies for an exchange?`, answer: `No. We coordinate identification, sourcing, and communication among your advisors. Whether a specific Flower Mound transaction qualifies for tax deferral is determined by your CPA, tax attorney, and qualified intermediary.` },
    ],
  },
  "coppell-tx": {
    sections: [
      { heading: null, html: `<p>Coppell's location right next to DFW International Airport turned it into a genuine logistics hub years before the rest of the corridor caught on, and that history still shapes what an owner is actually selling here. Most Coppell exchanges today still involve a distribution building, Freeport-zoned warehouse space, or corporate office space along the SH 121 corridor, and each of those categories draws a different pool of buyers once the property goes to market.</p>` },
      { heading: `The Logistics-Driven Coppell Commercial Base`, html: `<p>Coppell's proximity to DFW Airport and its highway access along SH 121 and MacArthur Boulevard have pulled distribution and corporate tenants here for decades. The categories that come up most often include:</p><ul><li>Distribution and warehouse buildings near DFW Airport and SH 121</li><li>Freeport-zoned logistics space benefiting from inventory tax exemption</li><li>Corporate office campuses along the SH 121 and MacArthur Boulevard corridor</li><li>Flex and light-manufacturing buildings serving the surrounding industrial park</li><li>DST interests for owners exiting active logistics property management</li></ul>` },
      { heading: `Identification Strategy for Freeport-Zoned Property`, html: `<p>An owner trading one Freeport-zoned distribution building for a comparable one nearby can typically use the three-property rule, since that kind of logistics product is well represented across the corridor. An investor exiting corporate office and considering distribution, flex, or a DST as replacement candidates usually needs the 200 percent rule, because those categories carry different lease structures and rarely compare cleanly enough to narrow to three options with confidence before the deadline.</p>` },
      { heading: `Diligence Specific to Coppell's Logistics Stock`, html: `<p>Freeport exemption status is not automatic and should be confirmed directly with the appraisal district rather than assumed to carry over from the seller's prior tax bill. Clear height, dock door count, and trailer parking capacity matter more to logistics tenants here than in most other property types, so a buyer should verify those specifications match current tenant requirements rather than relying on a building's age or square footage alone. Corporate office near SH 121 should be checked for tenant concentration, since several buildings in this corridor were originally leased to a single large corporate user and can take longer to re-tenant if that user leaves. Rail access along the corridor is another point worth confirming directly with the railroad rather than a listing sheet, since a spur that once served a distribution building can go inactive without any visible change to the site itself, and that status affects both marketability and achievable rent for future tenants.</p>` },
      { heading: `Financing Around Airport-Adjacent Logistics Timing`, html: `<p>Lenders financing distribution and warehouse property near DFW Airport often want confirmation of clear height and loading specifications before finalizing terms, since those details drive the building's marketability to future logistics tenants. A Coppell buyer should have that specification sheet ready before approaching a lender, because a mismatch discovered mid-underwriting can push financing past the point where it still fits inside the exchange timeline. Lenders unfamiliar with Freeport exemption mechanics sometimes underestimate a buyer's effective carrying cost, so walking the lender through that exemption directly can prevent an overly conservative debt-service calculation from slowing the loan down.</p>` },
      { heading: `What a Clean Coppell Exchange Looks Like`, html: `<p>The investors who move efficiently through a Coppell exchange confirm Freeport status and building specifications early rather than assuming logistics product is interchangeable, and they choose an identification rule that matches whether they are staying inside distribution property or spreading across office and flex categories as well. Given how tightly logistics tenants specify their space requirements, a buyer who tours a candidate building without a target tenant's specification sheet in hand is effectively guessing at whether the property will actually lease at the assumed rate once the current tenant's term ends.</p>` },
    ],
    faqs: [
      { question: `Does Freeport tax exemption transfer automatically with a Coppell property sale?`, answer: `No. Freeport-zoned status should be confirmed directly with the appraisal district rather than assumed to carry over automatically, since exemption eligibility depends on how the inventory is used and reported, and a change in tenant or use can affect whether the exemption still applies going forward after closing on the purchase.` },
      { question: `Why do clear height and dock door count matter so much in Coppell logistics deals?`, answer: `Logistics tenants have specific requirements for clear height, dock door count, and trailer parking, and a mismatch with current tenant standards can limit a building's marketability more than its age or square footage would suggest, sometimes significantly.` },
      { question: `Should I use the three-property rule for a Coppell warehouse-to-warehouse trade?`, answer: `Often yes, since comparable Freeport-zoned distribution buildings are well represented across the corridor. An investor diversifying into office or flex candidates alongside distribution usually needs the 200 percent rule instead, given how differently those categories are underwritten and leased.` },
      { question: `How does tenant concentration affect Coppell corporate office as a replacement property?`, answer: `Several buildings in this corridor were originally leased to a single large corporate tenant, so a buyer should review lease rollover exposure carefully rather than treating the current occupancy rate as a full picture of stability. Re-tenanting a large single-user building can take considerably longer than filling a multi-tenant office property, which affects both financing terms and pricing.` },
      { question: `Can 1031 Exchange Dallas confirm my Coppell property qualifies for an exchange?`, answer: `No. This service coordinates planning, property identification, and communication among the investor's advisors. Whether a specific transaction and property qualify is a determination made by the investor's CPA, tax attorney, and qualified intermediary.` },
    ],
  },
  "garland-tx": {
    sections: [
      { heading: null, html: `<p>Garland is one of the metro's older inner-ring suburbs, and its commercial base reflects decades of manufacturing and light-industrial history along the I-30 and Centerville corridor rather than the newer master-planned campuses found further north. Workforce multifamily built to house that industrial labor base makes up a large share of the residential-adjacent commercial stock, and retail along Garland Road and Broadway serves an established, long-settled population rather than a fast-growing rooftop count. Institutional buyers trade less frequently here than in the newer northern suburbs, which means an exchanger sourcing Garland replacement property should expect a slower, more relationship-driven deal flow than a Legacy-corridor or Frisco transaction, with more of the useful data on a given property coming from the current owner or a local broker than from a database of recent comparable sales.</p>` },
      { heading: `Older Industrial and Manufacturing Stock Along I-30 and Centerville`, html: `<p>Garland's industrial base grew up around decades-old manufacturing and light-assembly buildings, many originally built for electronics or garment-related production, and this vintage of building sometimes carries lower clear heights and older electrical or fire-suppression systems than a distribution tenant expects today. A buyer should request a specific capital plan for any needed system upgrades before underwriting the deal as a straight income acquisition, since the true cost of bringing an older Garland industrial building up to current tenant standards can be substantial relative to the purchase price. Some of these buildings sit on larger parcels than their footprint requires, a legacy of an earlier era of manufacturing site planning, and a buyer should confirm whether any excess land carries separate development potential or simply adds to the tax and maintenance burden without a clear path to added value.</p>` },
      { heading: `Workforce Multifamily Serving Garland's Industrial Labor Base`, html: `<p>Multifamily product here generally serves a working-class tenant base tied historically to the surrounding industrial and manufacturing employment, and this product tends to show different turnover and collection patterns than the newer, amenity-heavy multifamily found in faster-growing suburbs. A buyer should review trailing turnover and delinquency data closely and confirm whether recent capital improvements have kept pace with deferred maintenance, since older workforce housing stock in an inner-ring suburb can carry more deferred capital needs than the trailing income statement alone reveals. A property inspection covering roofs, parking surfaces, and plumbing systems original to the building is worth commissioning before identification rather than after, given how often deferred maintenance on this vintage of multifamily only becomes visible once a new owner starts making capital repairs.</p>` },
      { heading: `Garland Road and Broadway Retail`, html: `<p>Retail along Garland Road and Broadway generally serves an established, long-settled resident population with grocery-anchored centers and freestanding pad sites rather than the newer lifestyle-center format found in faster-growing suburbs. A diligence file for this corridor typically includes:</p><ul><li>Anchor tenant sales performance history, where available</li><li>Remaining primary lease term and renewal option structure</li><li>Co-tenancy clause review against current center occupancy</li><li>Deferred maintenance assessment on older center infrastructure</li><li>Phase I environmental site assessment</li><li>Tenant estoppel certificates</li></ul><p>Reviewing anchor tenant sales performance is worth the extra step in an established, slower-growth corridor like this one, since a grocery anchor's own health matters more to a center's stability than in a fast-growing suburb where new rooftop demand can carry a weaker anchor.</p>` },
      { heading: `Identification Timing in a Lower-Volume Trading Market`, html: `<p>Because institutional buyers trade less frequently in Garland than in the newer northern suburbs, an exchanger sourcing replacement property here should expect fewer comparable transactions to lean on when finalizing a purchase price, and building in extra time for a broker or seller to produce trailing financials is worth planning around inside the 45-day identification window rather than assuming a fast-moving northern-suburb pace.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Older Garland Assets`, html: `<p>Lenders financing an older Garland industrial or multifamily acquisition typically request a property condition assessment in more detail than they would for newer product, given the age of the building stock, and getting that assessment ordered early helps keep the loan process on pace for the 180-day closing deadline. The qualified intermediary holds exchange proceeds throughout and releases them at closing; this describes process and coordination only, and Garland exchangers should confirm tax treatment with their own advisor.</p>` },
    ],
    faqs: [
      { question: `Why might an older Garland industrial building need more capital investment than the purchase price suggests?`, answer: `Many buildings here were built decades ago for electronics or garment-related manufacturing and carry lower clear heights or older systems. Request a specific capital plan for upgrades before underwriting the deal as a straight income acquisition.` },
      { question: `What should I check on Garland workforce multifamily before identifying it?`, answer: `Review trailing turnover and delinquency data closely and confirm whether recent capital improvements have kept pace with deferred maintenance, since older workforce housing can carry more deferred capital needs than the income statement shows.` },
      { question: `Does anchor tenant health matter more for Garland Road retail than elsewhere?`, answer: `It can. In an established, slower-growth corridor, a grocery anchor's own sales performance matters more to center stability than in a fast-growing suburb where new rooftop demand can support a weaker anchor.` },
      { question: `Should I expect a fast transaction pace sourcing replacement property in Garland?`, answer: `Not necessarily. Institutional buyers trade less frequently here than in newer northern suburbs, so building in extra time for a seller to produce trailing financials is worth planning around inside the 45-day identification window.` },
      { question: `Do lenders request anything extra on older Garland industrial or multifamily deals?`, answer: `Often a more detailed property condition assessment given the age of the building stock. The qualified intermediary still holds and directs exchange funds; this is process description only, and investors should confirm tax treatment with their own advisor.` },
    ],
  },
  "mesquite-tx": {
    sections: [
      { heading: null, html: `<p>Mesquite sits east of downtown Dallas along I-635 and US 80, and its commercial base leans older and more industrial than the newer suburbs pushing north. An owner selling here is usually dealing with a rail-served warehouse, a strip center near Town East Mall, or a smaller light-manufacturing building along Military Parkway, and none of those replacement searches move at the same pace once the identification clock starts running.</p>` },
      { heading: `The Property Types That Actually Move in Mesquite`, html: `<p>Mesquite's commercial stock reflects decades of blue-collar industrial development alongside retail built for a growing residential base. The recognizable categories an owner is typically choosing among include:</p><ul><li>Rail-served warehouse and light-manufacturing buildings near the I-635/US 80 corridor</li><li>Strip retail and pad sites around Town East Mall</li><li>Older flex and back-office buildings along Military Parkway</li><li>Multifamily and mixed residential-adjacent commercial parcels near growing residential pockets</li><li>DST interests for owners stepping back from active industrial ownership</li></ul>` },
      { heading: `Choosing Between the Three-Property and 200 Percent Rules`, html: `<p>An owner trading one Mesquite warehouse for a similar rail-served building elsewhere can generally stay within the three-property rule, since comparable industrial stock along I-635 is not hard to locate. Someone exiting an aging retail strip near Town East and diversifying into a mix of industrial and multifamily candidates usually needs the 200 percent rule instead, because that spread of asset classes rarely narrows to three clean options before the deadline arrives.</p>` },
      { heading: `Watchouts on Older Mesquite Industrial and Retail Stock`, html: `<p>A lot of Mesquite's industrial buildings predate current fire code and loading standards, so a buyer should confirm compliance rather than assume an older warehouse would pass inspection as-is. Rail spur access on paper does not always mean active rail service, and that distinction affects both value and tenant demand. Retail centers near Town East carry the same lease rollover risk as any aging mall-adjacent property, and an investor should verify anchor tenant health before treating a strip center's income as stable. Flood control and drainage easements along the Trinity River bottoms show up more often in Mesquite than in suburbs farther from the river, so any industrial parcel near that floodplain deserves a current survey rather than a decades-old plat.</p>` },
      { heading: `Lender Timing for Industrial Deals East of Dallas`, html: `<p>Financing an older industrial building often takes longer to underwrite than a stabilized retail purchase, since lenders want environmental and structural reports on buildings that have changed hands multiple times. A Mesquite buyer should get those reports moving as soon as a property is identified rather than waiting for the qualified intermediary to request them, because a Phase I environmental review alone can eat two or three weeks of the 180-day exchange period. If that Phase I flags a recommendation for a Phase II, the buyer needs to know immediately rather than late in the exchange period, since a second round of environmental testing on an older Mesquite industrial site can take longer than most lenders will wait without a firm remediation plan attached.</p>` },
      { heading: `What a Well-Run Mesquite Exchange Looks Like`, html: `<p>The investors who close cleanly out of Mesquite treat the property's age and asset class honestly from the start, ordering environmental and structural reports early rather than after a lender asks, and they pick an identification rule that matches how narrow or broad their actual replacement search is instead of defaulting to whichever rule worked on the last deal. Given how much of Mesquite's stock predates modern building standards, it is worth budgeting extra time for diligence on any property built before the corridor's more recent development cycle, rather than assuming every industrial building in this submarket carries the same age and condition, since two buildings a few blocks apart can differ by twenty years or more.</p>` },
    ],
    faqs: [
      { question: `Is older industrial building age a problem for a Mesquite 1031 replacement?`, answer: `Age itself does not disqualify a property, but older buildings often need updated environmental and structural reports before a lender will finance them, so those reports should be ordered as soon as the property is identified rather than later in the process. A building that changed ownership several times without updated records tends to need a more thorough review than one with a single long-term prior owner.` },
      { question: `How do I know if rail spur access at a Mesquite warehouse is still active?`, answer: `Paper access does not guarantee active service. An investor should confirm current rail service directly with the operating railroad rather than relying on a listing description, since inactive spurs affect both tenant demand and value.` },
      { question: `Should I use the three-property rule or the 200 percent rule for a Mesquite industrial trade?`, answer: `A like-for-like industrial trade with comparable rail-served buildings available usually fits the three-property rule. An investor diversifying into a mix of industrial, retail, and multifamily candidates typically needs the 200 percent rule to keep enough options open.` },
      { question: `How long does financing take on an older Mesquite industrial building?`, answer: `Longer than a stabilized retail purchase in most cases, since lenders often require a Phase I environmental report and structural review before underwriting. Ordering those reports immediately after identification helps avoid losing time inside the 180-day exchange period.` },
      { question: `Can 1031 Exchange Dallas confirm my Mesquite property qualifies for an exchange?`, answer: `No. This service coordinates planning, property sourcing, and communication among the investor's advisors. Whether a specific transaction and property qualify is a determination made by the investor's CPA, tax attorney, and qualified intermediary.` },
    ],
  },
  "fort-worth-tx": {
    sections: [
      { heading: null, html: `<p>Fort Worth trades on a different mix than the rest of the metro. Medical and lab space clusters around the Near Southside hospital campuses, hospitality and entertainment product ties to the Cultural District's museum row and the Dickies Arena calendar, and adaptive-reuse retail fills the historic Stockyards district. Downtown carries an older office stock that keeps producing residential-conversion candidates as owners reposition floors that no longer compete for corporate tenants. An exchanger moving proceeds into Fort Worth is usually choosing between a stabilized medical-office lease and a value-add conversion or adaptive-reuse play, and those two paths carry different diligence lists and different amounts of runway before the 45-day identification deadline closes.</p>` },
      { heading: `Medical and Lab Office Near the Near Southside Hospital Campuses`, html: `<p>Texas Health Harris Methodist Fort Worth, Cook Children's Medical Center, and the UNT Health Science Center anchor a medical office and lab corridor just south of downtown, and the tenant base there skews toward physician groups, diagnostic imaging operators, and research tenants who sign longer leases because their buildout is expensive to relocate. A buyer identifying a Near Southside medical building as replacement property should pull the tenant improvement allowance history and compare remaining lease term against buildout amortization, since a short remaining term on a heavily built-out suite can signal renewal risk regardless of the current rent roll. Ground-floor retail along Magnolia Avenue supports a separate, shorter-term leasing pattern serving the walkable restaurant and neighborhood-retail crowd drawn by the medical campus workforce.</p>` },
      { heading: `Cultural District Hospitality Tied to the Museum and Arena Calendar`, html: `<p>The Kimbell, the Modern, and the Amon Carter museums, together with Dickies Arena, draw event-driven hotel and short-term hospitality demand into the Cultural District, and boutique hotel and event-adjacent retail are the typical asset types an exchanger sees listed there. Occupancy and average rate at these properties can swing considerably with the arena's rodeo, equestrian, and concert calendar, so a buyer should review trailing revenue per available room across a full operating year rather than relying on figures pulled from peak-event months. Confirming which months carried the trailing numbers matters more here than in a straight multifamily or office underwriting, since a partial-year sample can misstate what stabilized performance actually looks like.</p>` },
      { heading: `Stockyards and Near Northside Adaptive Reuse`, html: `<p>The Stockyards Historic District, including Mule Alley and the Livestock Exchange Building, has been repositioned into hospitality, entertainment, and boutique retail inside century-old masonry structures, and several of those buildings carry historic designation or preservation-easement terms that limit what alterations a new owner can make without approval. A due-diligence file for Stockyards or Near Northside replacement property typically includes:</p><ul><li>Historic designation and preservation-easement review</li><li>Title and easement search for century-old parcels</li><li>Structural and roof condition report</li><li>Ground lease versus fee-simple confirmation</li><li>Parking allocation and access rights</li><li>Phase I environmental site assessment</li><li>Tenant estoppel certificates</li></ul><p>Confirming whether a property sits under a ground lease is worth checking early, since several Stockyards parcels are held that way and it changes both financing and the identification description an exchanger needs to file.</p>` },
      { heading: `Identification Timing Between Stabilized and Value-Add Fort Worth Product`, html: `<p>An exchanger weighing a stabilized Near Southside medical building against a downtown conversion candidate or a Stockyards adaptive-reuse property often names both under the three-property or 200% rule, keeping the stabilized asset as the frontrunner while additional structural and historic-compliance inspection work happens on the conversion candidate. Conversion and adaptive-reuse properties usually need more inspection time than a straight leased asset, and starting that inspection scheduling before the formal identification letter goes out helps avoid running the 45-day window down to the last few days on a property that may not clear diligence.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Conversion Candidates`, html: `<p>Lenders underwriting a Fort Worth conversion or adaptive-reuse acquisition typically request an updated appraisal and feasibility work beyond what a stabilized leased asset requires, and getting that request in front of the lender early tends to prevent a late-stage delay heading into the 180-day closing deadline. The qualified intermediary holds exchange proceeds throughout this process and releases them to the closing table once the transaction is ready; this describes process and coordination only, and Fort Worth exchangers should confirm the tax treatment of any conversion or reuse property with their own tax advisor before closing.</p>` },
    ],
    faqs: [
      { question: `Why do Near Southside medical buildings tend to carry longer lease terms than other Fort Worth product?`, answer: `Physician and diagnostic tenants build out expensive space that is costly to relocate, so they typically sign longer terms. Check the tenant improvement allowance history and remaining lease term against buildout amortization before identifying the building.` },
      { question: `Does Cultural District hospitality carry more seasonal risk than other asset classes?`, answer: `Yes. Occupancy and rate can swing with the museum and arena event calendar, so review trailing revenue per available room across a full operating year rather than peak-event months alone.` },
      { question: `What makes a Stockyards building different from a typical retail acquisition elsewhere in the metro?`, answer: `Many Stockyards structures carry historic designation or preservation-easement terms that limit alterations and can affect financing. Confirm designation status and any easement terms before identification.` },
      { question: `Should I identify a downtown conversion candidate alongside a stabilized medical building?`, answer: `Many exchangers do, under the three-property or 200% rule, so inspection work on the conversion candidate can continue while the stabilized asset remains the frontrunner, as long as combined identified value stays within the applicable threshold.` },
      { question: `Do lenders treat adaptive-reuse collateral differently than a stabilized leased building?`, answer: `Often, yes, requesting updated appraisal or feasibility work beyond what a stabilized asset needs. The qualified intermediary still holds and directs exchange funds; this is process description only, and investors should confirm tax treatment with their own advisor.` },
    ],
  },
  "dallas-tx": {
    sections: [
      { heading: null, html: `<p>Dallas proper covers a wide range of submarkets, from the dense urban core to the industrial belt along the southern edge of the city, and a citywide replacement search has to account for that range rather than treating Dallas as a single, uniform market. An owner selling anywhere in the city limits should think in terms of which submarket their asset actually competes in, not the city boundary alone.</p>` },
      { heading: `Dallas's Split Personality: Urban Core Density and Southern Dallas Industrial Growth`, html: `<p>North of the Trinity River, Dallas trades on urban density, walkability, and office and multifamily rents that rival any submarket in the metro. South of the river, the city has become one of the fastest-growing industrial corridors in North Texas, driven by land availability and highway access that the northern half of the city no longer has. An owner exchanging citywide should treat these as functionally separate markets when building an identification list.</p>` },
      { heading: `The Inland Port and I-20/I-45 Industrial Corridor`, html: `<p>The Dallas Inland Port along I-20 and I-45 in southern Dallas County has drawn major logistics and distribution users, taking advantage of proximity to both Interstate highways and rail access without the land cost pressure found closer to the urban core. Investors identifying industrial replacement property should compare Inland Port candidates against similar product near Interstate 30 or the DFW Airport corridor, since lease structures and tenant quality can vary meaningfully between them. Rail-served sites in this corridor command a premium over truck-only sites for certain distribution tenants, so a buyer should confirm whether active rail service actually reaches a candidate building rather than assuming a nearby line means the site is served.</p>` },
      { heading: `Opportunity Zone Overlap With 1031 Candidates in Southern Dallas`, html: `<p>Several southern Dallas census tracts carry federal Opportunity Zone designation, which is a separate tax incentive program from a 1031 exchange and uses different rules, timelines, and gain treatment. An investor considering a property inside an Opportunity Zone as a 1031 replacement should not assume the two programs stack automatically, and should confirm the interaction with their tax advisor before relying on both benefits in the same underwriting model.</p>` },
      { heading: `Identification Strategy When Comparing Submarkets Across the Whole City`, html: `<p>A citywide Dallas search that spans urban core office or multifamily and southern Dallas industrial usually benefits from the two hundred percent rule, since those asset types do not compare cleanly enough to narrow a list to three candidates early in the process. An investor staying within one submarket and one property type can generally work within the three property rule instead.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination for Citywide Dallas Searches`, html: `<p>Because a citywide search can span very different lender appetites, from urban core construction-adjacent financing to straightforward industrial debt, we coordinate early with both the qualified intermediary and whichever lender is financing the leading candidate, so the exchange timeline is not driven by whichever submarket happens to move slowest.</p>` },
    ],
    faqs: [
      { question: `Why does industrial development keep expanding in southern Dallas?`, answer: `The Dallas Inland Port along I-20 and I-45 offers land availability and highway and rail access that the northern half of the city no longer has, which has drawn logistics and distribution users looking for space without the land cost pressure closer to the urban core.` },
      { question: `Can I combine an Opportunity Zone investment with my 1031 exchange in Dallas?`, answer: `The two programs use different rules and timelines and do not automatically stack. An investor considering a property inside a Dallas Opportunity Zone as a 1031 replacement should confirm the interaction with their CPA or tax attorney before assuming both benefits apply together.` },
      { question: `Should I compare urban core Dallas office to southern Dallas industrial in the same identification list?`, answer: `They generally behave as separate markets with different tenant profiles and risk, so a citywide search spanning both usually benefits from the 200 percent rule rather than trying to force a narrow three property list across two very different asset types.` },
      { question: `How does financing differ between Inland Port industrial and other Dallas industrial submarkets?`, answer: `Lease structures and tenant quality can vary meaningfully between the Inland Port, the I-30 corridor, and the DFW Airport-adjacent industrial market, so lender underwriting and financing terms should be compared candidate by candidate rather than assumed to be uniform across the city.` },
      { question: `Can 1031 Exchange Dallas confirm my Dallas property qualifies for an exchange?`, answer: `No. We coordinate identification, sourcing, and communication among your advisors. Whether a specific Dallas transaction qualifies for tax deferral is determined by your CPA, tax attorney, and qualified intermediary.` },
    ],
  },
  "nationwide": {
    sections: [
      { heading: null, html: `<p>Not every Dallas investor wants their replacement property to stay in Dallas, and a growing share of the exchanges we support involve a Dallas-area seller identifying candidates in other states entirely. Like-kind exchange rules apply to real property held for investment anywhere in the United States, so geography is a strategic choice, not a legal constraint.</p>` },
      { heading: `Why Dallas Investors Look Beyond Texas for Replacement Property`, html: `<p>Investors selling appreciated Dallas real estate sometimes want to diversify out of a single metro's economic cycle, chase yield in a market where Dallas-level pricing does not apply, or move closer to family or a second home in another state. None of those reasons change the mechanics of the exchange, since Texas has no state income tax to reconcile, but they do change how we build the identification and diligence process around unfamiliar markets. A Dallas seller moving into a state that does levy income tax should also flag that difference for their CPA early, since it can affect the after-tax economics of the replacement purchase even though the federal exchange mechanics stay the same.</p>` },
      { heading: `Matching a Sunbelt Exit to Markets With Different Cycle Timing`, html: `<p>Dallas has led several recent development cycles, particularly in multifamily and industrial, which means some out-of-state markets are earlier in their own supply cycle and can offer better entry pricing for a similar asset type. An investor exchanging out of a fully priced Dallas asset should weigh where the replacement market sits in its own cycle, not just its current cap rate relative to Dallas.</p>` },
      { heading: `DST and TIC Access When a Nationwide Direct Purchase Is Too Slow`, html: `<p>For investors who want geographic diversification but do not want to manage due diligence and closing logistics in an unfamiliar state inside the forty five day window, Delaware Statutory Trust and tenancy in common interests can qualify as like-kind replacement property under current guidance and are sourced through licensed securities professionals we can introduce, since these structures are generally offered as securities and that portion of the transaction sits outside our role.</p>` },
      { heading: `Identification Strategy When Candidates Sit in Different Time Zones`, html: `<p>A nationwide search spanning multiple time zones and legal jurisdictions benefits from the two hundred percent rule almost by default, since due diligence timelines, title company practices, and closing customs vary enough state to state that keeping a narrow three property list can leave an investor with no workable backup if one candidate falls through.</p>` },
      { heading: `Qualified Intermediary and Lender Coordination Across State Lines`, html: `<p>We coordinate closely with the qualified intermediary and whichever local title company and lender are handling the out-of-state closing, since document customs, recording timelines, and even standard closing costs vary by state in ways that can catch a Texas-based investor off guard if they are not flagged early in the process.</p>` },
    ],
    faqs: [
      { question: `Can I exchange a Dallas property for a replacement property in another state?`, answer: `Yes. Like-kind exchange rules apply to real property held for investment anywhere in the United States, so a Dallas seller can identify and acquire replacement property nationwide without losing eligibility for gain deferral.` },
      { question: `Why would a Dallas investor want to buy in a market outside Texas?`, answer: `Common reasons include diversifying out of a single metro's economic cycle, finding entry pricing that Dallas no longer offers after a strong run-up, or targeting a market earlier in its own supply cycle for a similar asset type.` },
      { question: `Are DST and TIC interests a good option for a nationwide exchange?`, answer: `They can be, particularly for investors who want geographic diversification without managing out-of-state closing logistics inside the forty five day window. These structures are generally offered as securities, so that part of the transaction is handled by licensed securities professionals we can introduce.` },
      { question: `Should I use the three property rule for a nationwide identification list?`, answer: `Usually not by itself. A search spanning multiple states and time zones typically benefits from the 200 percent rule, since due diligence and closing customs vary enough by state that a narrow three property list can leave no workable backup if one candidate falls through.` },
      { question: `Can 1031 Exchange Dallas confirm my out-of-state replacement property qualifies for an exchange?`, answer: `No. We coordinate identification, sourcing, and communication among your advisors nationwide. Whether a specific transaction qualifies for tax deferral is determined by your CPA, tax attorney, and qualified intermediary.` },
    ],
  },
};

export function getLocationContent(slug: string): LocationContentEntry | undefined {
  return (
    locationContent[slug] ||
    locationContent[`${slug}-tx`] ||
    locationContent[slug.replace(/-tx$/, "")]
  );
}
